const a={1:[["1","Mısır'a gelen İsrael'in oğullarının adları şunlardır (her biri ve onun ev halkı Yakov'la birlikte geldi):"],["2","Ruven, Şimon, Levi, Yahuda,"],["3","İsakar, Zevulun, Benyamin,"],["4","Dan, Naftali, Gad ve Aşer."],["5","Yakov'un bedeninden gelen canların tümü yetmiş candı ve Yosef zaten Mısır'daydı."],["6","Yosef de kardeşleri ve tüm o kuşak gibi öldü."],["7","İsrael'in çocukları verimli oldular, bolca artıp çoğaldılar, fazlasıyla güçlendiler ve ülke onlarla doldu."],["8","Şimdi Mısır üzerinde Yosef'i tanımayan yeni bir kral çıktı."],["9","Halkına şöyle dedi, “İşte , İsrael'in çocuklarının halkı bizden daha çok ve daha güçlü."],["10","Gelin, onlara karşı bilgece davranalım, yoksa çoğalacaklar, olur da bir savaş çıkarsa, onlar da düşmanlarımıza katılıp bize karşı savaşır ve ülkeden kaçarlar."],["11","Bu nedenle yükleriyle onlara sıkıntı çektirmek için üzerlerine angarya görevlileri atadılar."],["12","Ama onlara ne kadar eziyet ettilerse, onlar o kadar çok çoğaldılar ve daha da yayıldılar."],["13","Mısırlılar İsrael'in çocuklarına acımasızca hizmet ettirdiler."],["14","Her türlü tarla işi, harç ve kerpiç işi gibi ağır işlerle hayatlarını zehir ettiler, onları acımasızca hizmet ettirdiler."],["15","Mısır Kralı, birinin adı Şifrah, diğerinin adı Puah olan İbrani ebelerle konuştu."],["16","Ve şöyle dedi, “İbrani kadınlara ebelik yaptığınızda, onları doğum sandalyesinde gördüğünüzde, eğer çocuk erkekse, öldürün, kızsa yaşasın.”"],["17","Ama ebeler Tanrı'dan korktular, Mısır Kralı'nın kendilerine buyurduğu şeyi yapmayıp, erkek çocukları canlı kurtardılar."],["18","Mısır Kralı ebeleri çağırıp onlara, “Neden bunu yapıp erkek çocukları canlı kurtardınız?” dedi."],["19","Ebeler Firavun'a şöyle dediler, “Çünkü İbrani kadınlar Mısırlı kadınlara benzemiyor. Onlar güçlü oldukları için ebe yanlarına gelmeden doğum yapıyor.”"],["20","Tanrı ebelere iyi davrandı ve halk çoğalıp fazlasıyla güçlendi."],["21","Ebeler Tanrı'dan korktukları için Tanrı onlara aileler verdi."],["22","Firavun halkının tümüne şöyle buyurdu, “Doğan her erkek çocuğu nehre atın, her kız çocuğu canlı kurtarın.”"]],2:[["1","Levi evinden bir adam gitti ve bir Levi kızını aldı."],["2","Kadın gebe kaldı ve bir oğul doğurdu. Kadın çocuğun güzel olduğunu görünce onu üç ay sakladı."],["3","Artık onu daha fazla gizleyemeyince, papirüs ağacından bir sepet alıp onu katranla kapladı. Çocuğu içine koydu ve nehrin kıyısındaki sazlığa bıraktı."],["4","Kız kardeşi ona ne olacağını görmek için uzakta duruyordu."],["5","Firavun'un kızı yıkanmak için nehre indi. Onun hizmetçileri nehrin kenarında yürüyorlardı. Sazların arasındaki sepeti gördü ve onu alması için hizmetçilerini gönderdi."],["6","Onu açtı ve çocuğu gördü. İşte bebek ağlıyordu. Ona acıdı ve şöyle dedi, “Bu İbraniler'in çocuklarından biridir.”"],["7","Bunun üzerine kız kardeşi, Firavun'un kızına, “Çocuğu emzirmesi için sana İbrani kadınlardan bir dadı çağırayım mı?” dedi."],["8","Firavun'un kızı ona, “Git” dedi. Genç kız gidip çocuğun annesini çağırdı."],["9","Firavun'un kızı ona, “Bu çocuğu al ve benim için emzir, ben de ücretini veririm” dedi. Kadın çocuğu alıp emzirdi."],["10","Çocuk büyüdü ve kadın onu Firavun'un kızına getirdi ve onun oğlu oldu. Ona Moşe adını verdi, “Çünkü onu sudan çıkardım” dedi."],["11","Moşe büyüdüğü o günlerde kardeşlerinin yanına çıktı ve onların yüklerini gördü. Bir Mısırlı'nın kardeşlerinden biri olan bir İbrani'ye vurduğunu gördü."],["12","Çevresine bakınıp kimsenin olmadığını görünce Mısırlı'yı öldürüp kumun içine sakladı."],["13","Ertesi gün çıktı, işte iki İbrani birbiriyle kavga ediyordu. Yanlış yapana, “Neden arkadaşına vuruyorsun?” dedi."],["14","Adam, “Kim seni üzerimize bey ve yargıç yaptı? Mısırlı'yı öldürdüğün gibi beni de öldürmeyi mi tasarlıyorsun?” dedi. Moşe korktu, “Bu şey kesin biliniyor” dedi."],["15","Firavun bunu duyunca Moşe'yi öldürmeye çalıştı. Ama Moşe Firavun'un önünden kaçtı ve Midyan diyarında yaşadı ve bir kuyunun yanına oturdu."],["16","Midyanlı bir kâhinin yedi kızı vardı. Gelip su çektiler ve babalarının sürüsünü sulamak için yalakları doldurdular."],["17","Çobanlar gelip onları uzaklaştırdı. Ama Moşe kalktı ve onlara yardım etti ve sürülerini suladı."],["18","Babaları Reuel'in yanına vardıklarında o, “Nasıl oldu da bugün bu kadar erken geldiniz?” dedi."],["19","Onlar, “Mısırlı bir adam bizi çobanların elinden kurtardı, üstelik bizim için su çekip sürüyü suladı” dediler."],["20","Adam kızlarına, “Nerede o? Adamı neden bıraktınız? Onu çağırın da yemek yesin” dedi."],["21","Moşe adamın yanında kalmaktan hoşnuttu. Adam kızı Sipporah'ı Moşe'ye verdi."],["22","Bir oğul doğurdu ve o, adını Gerşom koydu; “Çünkü yabancı bir diyarda garip olarak yaşıyorum” dedi."],["23","Aradan çok sayıda günler gelip geçti, Mısır Kralı öldü. İsrael'in çocukları esaretten dolayı ah çektiler, feryat ettiler ve feryatları esaret nedeniyle Tanrı'ya ulaştı."],["24","Tanrı onların iniltilerini duydu ve Tanrı Avraham'la, İshak'la ve Yakov'la yaptığı antlaşmayı hatırladı."],["25","Tanrı İsrael'in çocuklarını gördü ve Tanrı anladı."]],3:[["1","Moşe, kayınpederi Midyanlı Yetro'nun sürüsünü güdüyordu. Sürüyü çölün arka tarafına götürüp Tanrı Dağı'na, Horev'e geldi."],["2","Yahve'nin meleği bir çalının ortasındaki alevin içinde ona göründü. Baktı, işte, çalı ateşte yanıyordu ama tükenmiyordu."],["3","Moşe, “Şimdi gidip bu büyük manzarayı, çalının neden tükenmediğini göreyim” dedi."],["4","Yahve onun bakmaya geldiğini görünce, Tanrı ona çalının ortasından seslenip şöyle dedi, “Moşe! Moşe!” O, “İşte buradayım” dedi."],["5","“Yaklaşma. Çarıklarını çıkar, çünkü üzerinde durduğun yer kutsal topraktır” dedi."],["6","Üstelik, “Ben babanın Tanrısı, Avraham'ın Tanrısı, İshak'ın Tanrısı ve Yakov'un Tanrısı'yım” dedi. Moşe, yüzünü sakladı çünkü Tanrı'ya bakmaya korkuyordu."],["7","Yahve şöyle dedi, “Mısır'da olan halkımın sıkıntısını elbette gördüm, angarya görevlileri yüzünden feryatlarını duydum. Çünkü onların acılarını biliyorum."],["8","Onları Mısırlılar'ın elinden kurtarmak ve o ülkeden iyi ve geniş bir ülkeye süt ve bal akan bir ülkeye, Kenanlı, Hititli, Amorlu, Perizli, Hivli ve Yevuslular'ın yerine götürmek için aşağıya indim."],["9","İşte, İsrael çocuklarının feryadı bana ulaştı. Üstelik Mısırlılar'ın onlara ettiği zulmü gördüm."],["10","Bu nedenle şimdi gel, halkım İsrael'in çocuklarını Mısır'dan çıkarman için seni Firavun'a göndereyim.”"],["11","Moşe Tanrı'ya, “Ben kimim ki, Firavun'a gideyim de İsrael'in çocuklarını Mısır'dan çıkarayım?” dedi."],["12","Ve Tanrı, “Ben kesinlikle seninle olacağım. Seni gönderdiğimin belirtisi şu olacak, halkı Mısır'dan çıkardığın zaman, bu dağda Tanrı'ya hizmet edeceksiniz” dedi."],["13","Moşe Tanrı'ya şöyle dedi, “İşte, İsrael'in çocuklarının yanına gelip onlara, 'Beni size atalarınızın Tanrısı gönderdi' dediğimde, onlar bana, 'O'nun adı nedir?' diye sorduklarında, onlara ne diyeyim?”"],["14","Tanrı Moşe'ye, “BEN BEN OLAN'IM” dedi ve, “İsrael'in çocuklarına şunu diyeceksin” dedi: 'Beni size BEN'İM gönderdi.'”"],["15","Ayrıca Tanrı Moşe'ye, “İsrael'in çocuklarına böyle diyeceksin” dedi, “'Atalarınızın Tanrısı, Avraham'ın Tanrısı, İshak'ın Tanrısı ve Yakov'un Tanrısı Yahve beni size gönderdi.' Sonsuza dek adım bu ve bütün kuşaklarca anılmam budur."],["16","Git, İsrael'in ihtiyarlarını bir araya topla ve onlara şöyle de: 'Atalarınızın Tanrısı, Avraham'ın Tanrısı, İshak'ın Tanrısı ve Yakov'un Tanrısı Yahve bana göründü ve şöyle dedi: Sizi gerçekten ziyaret ettim ve Mısır'da size yapılanı gördüm."],["17","Dedim ki, sizi Mısır'ın sıkıntısından, Kenanlı Hititli, Amorlu, Perizli, Hivli ve Yevuslular'ın ülkesine, süt ve bal akan diyara götüreceğim.'"],["18","“Onlar sözünü dinleyecekler. Sen ve İsrael'in ihtiyarları Mısır Kralı'nın yanına gelip ona, 'İbraniler'in Tanrısı Yahve bizimle görüştü diyeceksiniz. Şimdi lütfen izin ver de Tanrımız Yahve'ye kurban sunmak için üç günlük bir yolculuk yapalım.'"],["19","Mısır Kralı'nın güçlü bir el aracılığıyla olsa bile gitmek için size izin vermeyeceğini biliyorum."],["20","Elimi uzatıp aralarında yapacağım harikalarla Mısır'ı vuracağım. Ondan sonra sizi bırakacak."],["21","Mısırlılar'ın gözünde bu halka lütuf vereceğim. Öyle ki, gittiğiniz zaman eli boş gitmeyeceksiniz."],["22","Ancak her kadın komşusundan ve evini ziyaret edenden gümüş takılar, altın takılar ve giysiler isteyecek. Bunları oğullarınızın ve kızlarınızın üzerine takacaksınız. Mısırlılar'ı yağmalayacaksınız.”"]],4:[["1","Moşe şöyle yanıt verdi, “Ama, işte, bana inanmayacaklar, ne de sözümü dinleyecekler, çünkü 'Yahve sana görünmedi' diyecekler.”"],["2","Yahve ona, “Elindeki nedir?” dedi. O, “Bir değnek” dedi."],["3","“Onu yere at” dedi. O yere attı ve bir yılan oldu. Moşe ondan kaçtı."],["4","Yahve Moşe'ye, “Elini uzat ve kuyruğundan tut” dedi. O elini uzattı ve tuttu. Elinde bir değnek oldu."],["5","“Bu atalarının Tanrısı, Avraham'ın Tanrısı, İshak'ın Tanrısı ve Yakov'un Tanrısı Yahve'nin sana göründüğüne iman etmeleri içindir.”"],["6","Yahve ayrıca ona, “Şimdi elini abanın içine koy” dedi. Elini abasının içine soktu ve onu çıkardığında, işte, eli kar gibi beyaz cüzamlıydı."],["7","“Elini yine abanın içine koy” dedi. Elini tekrar abasının içine soktu ve onu abasından çıkardığında, işte, yine diğer eti gibi olmuştu."],["8","“Eğer sana inanmazlarsa ya da ilk belirtinin sözünü dinlemezlerse, sonraki belirtinin sözüne inanacaklar."],["9","Eğer bu iki belirtiye de inanmazlarsa ya da sözünü dinlemezlerse, şöyle olacak, ırmağın suyundan alıp kuru toprağa dökeceksin. Irmaktan çıkaracağın su, kuru toprak üzerinde kana dönüşecek.”"],["10","Moşe Yahve'ye şöyle dedi, “Ey Efendim, ne önceden, ne de hizmetkârınla konuştuğundan beri güzel konuşan biri değilim. Çünkü ben konuşmada yavaşım ve yavaş dilliyim.”"],["11","Yahve ona şöyle dedi, “İnsanın ağzını yapan kim? Ya da insanı dilsiz, sağır, gören ya da kör yapan kimdir? Ben Yahve değil miyim?"],["12","Bu nedenle şimdi git, ben de senin ağzınla olacağım ve ne konuşacağını sana öğreteceğim.”"],["13","Moşe, “Ey Efendim, lütfen başka birisini gönder” dedi."],["14","Yahve Moşe'ye karşı öfkelendi ve şöyle dedi, “Peki ya kardeşin Levili Aron? Onun iyi konuşabildiğini biliyorum. Hem de, işte, o seni karşılamak için dışarı çıkıyor. Seni gördüğünde yüreği sevinecek."],["15","Onunla konuşacaksın ve sözleri onun ağzına koyacaksın. Ben senin ağzınla ve onun ağzıyla olacağım ve yapacağınız şeyi size öğreteceğim."],["16","O senin halka karşı sözcün olacak. Öyle olacak ki, o sana ağız ve sen de ona Tanrı gibi olacaksın."],["17","Belirtileri onunla yapacağın bu değneği eline alacaksın.”"],["18","Moşe gidip kayınpederi Yetro'nun yanına döndü ve ona, “Lütfen izin ver de gidip Mısır'daki kardeşlerimin yanına döneyim, onlar hâlâ hayatta mı göreyim?” dedi. Yetro Moşe'ye, “Esenlikle git” dedi."],["19","Yahve Midyan'da Moşe'ye şöyle dedi, “Git, Mısır'a dön; çünkü seni öldürmeye çalışan bütün insanlar öldü.”"],["20","Moşe karısını ve oğullarını alıp bir eşeğe bindirdi ve Mısır ülkesine döndü. Moşe Tanrı'nın değneğini eline aldı."],["21","Yahve Moşe'ye şöyle dedi, “Mısır'a döndüğün zaman, sana verdiğim bütün harikaları Firavun'un önünde yapmaya bak, ama ben onun yüreğini katılaştıracağım ve o, halkın gitmesine izin vermeyecek."],["22","Firavun'a de ki, 'Yahve diyor ki, İsrael benim ilk oğlum, ilk doğanımdır."],["23","Ben de sana, 'Oğlumu bırak, bana hizmet etsin' dedim ve sen onun gitmesine izin vermeyi reddettin. İşte, ilk doğan oğlunu öldüreceğim.'”"],["24","Yahve, konaklayacağı yere giderken yolda Moşe'yle karşılaştı ve onu öldürmek istedi."],["25","Bunun üzerine Sipporah bir çakmaktaşı alıp oğlunun sünnet derisini kesip ayaklarının dibine attı ve şöyle dedi, “Kesinlikle sen bana kan güveyisin.”"],["26","Bunun üzerine onu rahat bıraktı. Daha sonra sünnetten dolayı “Sen kan güveyisin” dedi."],["27","Yahve Aron'a, “Moşe'yi karşılamak için çöle git” dedi. Gidip Tanrı'nın dağında onunla karşılaştı ve onu öptü."],["28","Moşe, Yahve'nin kendisiyle gönderdiği tüm sözleri ve kendisine buyurmuş olduğu bütün belirtileri Aron'a anlattı."],["29","Moşe ile Aron gidip İsrael çocuklarının bütün ihtiyarlarını bir araya topladılar."],["30","Aron, Yahve'nin Moşe'ye söylediği bütün sözleri söyledi ve halkın önünde belirtileri yaptı."],["31","Halk iman etti ve Yahve'nin İsrael çocuklarını ziyaret ettiğini, onların sıkıntılarını gördüğünü duyunca başlarını eğerek tapındılar."]],5:[["1","Daha sonra Moşe ile Aron gelip Firavun'a şöyle dediler, “İsrael'in Tanrısı Yahve şöyle diyor, 'Halkımın gitmesine izin ver, çölde bana bayram etsinler.'”"],["2","Firavun şöyle dedi, “Yahve kim ki, İsrael'in gitmesine izin vermek için O'nun sözünü dinleyeyim? Yahve'yi tanımıyorum ve dahası İsrael'in gitmesine izin vermeyeceğim.”"],["3","Onlar, “İbraniler'in Tanrısı bizimle görüştü” dediler. Lütfen, çölde üç günlük yol almamıza izin ver ki, Tanrımız Yahve'ye kurban keselim. Yoksa üzerimize salgın hastalık ya da kılıçla inebilir.”"],["4","Mısır Kralı onlara şöyle dedi, “Ey Moşe ve Aron, neden halkı işlerinden alıkoyuyorsunuz? Yüklerinize geri dönün!”"],["5","Firavun, “İşte, şimdi ülke halkı çoktur, siz onları yüklerinden dinlendiriyorsunuz” dedi."],["6","Aynı gün Firavun halkın angarya görevlilerine ve memurlara şu emri verdi,"],["7","“Artık eskisi gibi halka kerpiç yapmaları için saman vermeyeceksiniz. Gidip kendileri için saman toplasınlar."],["8","Onlardan daha önce yaptıkları kerpiçlerin sayısını isteyeceksiniz. Ondan hiçbir şey eksiltmeyeceksiniz; çünkü onlar tembeldirler. Bu nedenle, 'Hadi gidip Tanrımız'a kurban keselim' diyerek bağırıyorlar."],["9","Adamların üzerine daha ağır işler yüklensinler ki, çalışsınlar. Yalan sözlere aldırış etmesinler.”"],["10","Halkın angarya görevlileri memurlarıyla birlikte dışarı çıktılar ve halka şöyle konuşup dediler, “Firavun şöyle diyor, 'Size saman vermeyeceğim."],["11","Siz gidin, bulduğunuz yerden saman alın; çünkü işinizden hiçbir şey eksiltilmeyecektir.'”"],["12","Böylece halk, saman için anız toplamak amacıyla tüm Mısır diyarına dağıldı."],["13","Angaryacılar aceleyle, “Saman varken olduğu gibi gündelik iş kotanızı doldurun!” diyorlardı!"],["14","Firavun'un angaryacılarının üzerlerine atadığı İsrael'in çocuklarının memurları dövüldü ve onlara, “Daha önce olduğu gibi kerpiç yapımında neden dün de bugün de kotanızı doldurmadınız?” diye soruldu."],["15","Bunun üzerine İsrael'in çocuklarının memurları gelip Firavun'a şöyle feryat ettiler, “Hizmetkârlarına neden böyle davranıyorsun?"],["16","Hizmetkârlarına saman verilmiyor ve bize, 'Kerpiç yap!' diyorlar. Ama işte hizmetkârların dövülüyor; ama suç senin kendi halkındadır.”"],["17","Ama Firavun, “Siz tembelsiniz” dedi. “Boş duruyorsunuz! Bu nedenle, 'Hadi gidip Yahve'ye kurban keselim' diyorsunuz."],["18","Bunun için şimdi gidin ve çalışın, çünkü size saman verilmeyecek; yine de aynı sayıda kerpiç teslim edeceksiniz!”"],["19","İsrael'in çocuklarının memurları, “Günlük kerpiç kotanızdan hiçbir şey eksiltmeyeceksiniz!” denildiğinde başlarının belada olduğunu anladılar."],["20","Firavun'un yanından çıkarken yolda durmakta olan Moşe ve Aron'la karşılaştılar."],["21","Onlara, “Yahve size baksın ve yargılasın” dediler, “Çünkü bizi Firavun'un ve hizmetkârlarının gözünde tiksindirici bir koku yaptınız, bizi öldürmeleri için ellerine bir kılıç verdiniz.”"],["22","Moşe Yahve'ye dönüp şöyle dedi, “Ey Efendi, neden bu halkın başına dert açtın? Beni neden gönderdin?"],["23","Senin adına konuşmak için Firavun'a geldiğimden beri, o bu halkın başına bela getirdi. Sen de halkını hiç kurtarmadın!”"]],6:[["1","Yahve Moşe'ye şöyle dedi, “Şimdi Firavun'a ne yapacağımı göreceksin; çünkü güçlü el ile onların gitmesine izin verecek ve güçlü el ile onları ülkesinden kovacak.”"],["2","Tanrı Moşe'ye konuşup ona şöyle dedi, “Ben Yahve'yim."],["3","Avraham'a, İshak'a ve Yakov'a Her Şeye Gücü Yeten Tanrı olarak göründüm, ama onlar beni Yahve adımla bilmiyordu."],["4","Ayrıca, yabancı olarak yaşadıkları, gezip dolaştıkları Kenan ülkesini onlara vermek üzere onlarla antlaşmamı kurdum."],["5","Üstelik Mısırlılar'ın esaret altında tuttuğu İsrael'in çocuklarının inlemelerini duydum ve antlaşmamı hatırladım."],["6","Bu nedenle İsrael'in çocuklarına de ki, 'Ben Yahve'yim ve sizi Mısırlılar'ın yükleri altından çıkaracağım, sizi onların esaretinden kurtaracağım ve uzanmış kolumla ve büyük hükümlerle sizi kurtaracağım."],["7","Sizi kendime bir halk olarak alacağım. Sizin Tanrınız olacağım ve bileceksiniz ki, sizi Mısırlılar'ın yükleri altından çıkaran Tanrınız Yahve benim."],["8","Avraham'a, İshak'a ve Yakov'a vermeye söz verdiğim ülkeye sizi getireceğim ve onu miras olarak size vereceğim. Ben Yahve'yim.'”"],["9","Moşe İsrael'in çocuklarına böyle söyledi, ama onlar ruh ıstırabından ve acımasız esaretten dolayı Moşe'yi dinlemediler."],["10","Yahve Moşe'ye şöyle konuştu,"],["11","“İçeri gir, Mısır Kralı Firavun'a İsrael çocuklarının ülkesinden gitmesine izin vermesini söyle.”"],["12","Moşe Yahve'nin huzurunda şöyle dedi, “İşte, İsrael'in çocukları beni dinlemediler. Dudaklarım sünnetsizken, Firavun beni nasıl dinleyecek?”"],["13","Yahve Moşe ve Aron'la konuştu ve onlara İsrael'in çocuklarına ve Mısır Kralı Firavun'a, İsrael'in çocuklarını Mısır diyarından çıkarmaları buyruğunu verdi."],["14","Bunlar babalarının evlerinin başlarıdır. İsrael'in ilk oğlu Ruven'in oğulları: Hanok ve Pallu, Hetsron ve Karmi. Bunlar Ruven'in aileleridir."],["15","Şimon'un oğulları: Yemuel, Yamin, Ohad, Yakin, Zohar ve Kenanlı bir kadının oğlu Şaul. Bunlar Şimon'un aileleridir."],["16","Kuşaklarına göre Levi oğullarının adları şunlardır: Gerşon, Kohat, Merari ve Levi'nin hayat yılları yüz otuz yedi yıldı."],["17","Gerşon'un oğulları: Ailelerine göre Livni ve Şimi."],["18","Kohat'ın oğulları: Amram, Yishar, Hebron, Uzziel. Kohat'ın hayat yılları yüz otuz üç yıldı."],["19","Merari'nin oğulları: Mahli ve Muşi. Kuşaklarına göre Levi boyları bunlardır."],["20","Amram babasının kız kardeşi Yokevet'i kendine eş olarak aldı ve ona Aron'la Moşe'yi doğurdu. Amram'ın hayat yılları yüz otuz yedi yıldı."],["21","Yishar'ın oğulları: Korah, Nefek ve Zikri."],["22","Uzziel'in oğulları: Mişael, Elsafan ve Sitri."],["23","Aron, Nahşon'un kız kardeşi Amminadav'ın kızı Elişeva'yı kendine eş olarak aldı ve ona Nadav'ı, Avihu'yu, Eleazar'ı ve İtamar'ı doğurdu."],["24","Korah'ın oğulları: Assir, Elkana ve Aviasaf. Bunlar Korahoğulları'nın aileleridir."],["25","Aron'un oğlu Eleazar Putiel'in kızlarından birini kendine eş olarak aldı ve ona Phinehas'ı doğurdu. Ailelerine göre Levililer'in babalarının başları bunlardır."],["26","Bunlar, Yahve'nin, “İsrael'in çocuklarının ordularına göre Mısır diyarından çıkarın” dediği Aron ve Moşe'dir."],["27","İsrael'in çocuklarını Mısır'dan çıkarmak için Mısır Kralı Firavun'la konuşanlar bunlardı. Bunlar Moşe ve Aron'dur."],["28","Yahve'nin Mısır'da Moşe'yle konuştuğu gün,"],["29","Yahve Moşe'ye şöyle dedi: “Ben Yahve'yim. Sana söyleyeceklerimin hepsini Mısır Kralı Firavun'a söyle.”"],["30","Moşe Yahve'nin huzurunda şöyle dedi, “İşte, ben sünnetsiz dudakları olan biriyim, Firavun beni nasıl dinleyecek?”"]],7:[["1","Yahve Moşe'ye şöyle dedi, “İşte, seni Firavun'a Tanrı gibi yaptım ve kardeşin Aron senin peygamberin olacak."],["2","Sana buyurduğum her şeyi söyleyeceksin ve kardeşin Aron Firavun'la konuşacak, ta ki, İsrael'in çocuklarının kendi ülkesinden gitmesine izin versin."],["3","Firavun'un yüreğini katılaştıracağım, Mısır diyarında belirtilerimi ve harikalarımı çoğaltacağım."],["4","Ama Firavun seni dinlemeyecek, o zaman elimi Mısır'ın üzerine koyacağım ve ordularımı, halkım İsrael'in çocuklarını, büyük hükümlerle Mısır diyarından çıkaracağım."],["5","Mısır'a elimi uzattığım ve İsrael çocuklarını aralarından çıkardığım zaman, Mısırlılar benim Yahve olduğumu bilecekler.”"],["6","Moşe ve Aron da öyle yaptılar. Yahve onlara nasıl buyurduysa öyle yaptılar."],["7","Firavun'la konuştuklarında Moşe seksen, Aron da seksen üç yaşındaydı."],["8","Yahve Moşe ve Aron'la konuşup şöyle dedi,"],["9","“Firavun seninle konuşup, 'Bir mucize gerçekleştir' derse, o zaman Aron'a, 'Değneğini al ve onu Firavun'un önüne at, değnek yılan olacak' diyeceksin.”"],["10","Moşe ile Aron Firavun'un yanına gittiler ve Yahve'nin buyurduğu gibi yaptılar. Aron değneğini Firavun'un ve hizmetkârlarının önüne attı ve değneği bir yılana dönüştü."],["11","Bunun üzerine Firavun bilgeleri ve büyücüleri de çağırdı. Mısır'ın büyücüleri, onlar da büyüleriyle aynı şeyi yaptılar."],["12","Çünkü her biri kendi değneğini attı ve yılana dönüştüler, ama Aron'un değneği onların değneklerini yuttu."],["13","Firavun'un yüreği katılaştı ve Yahve'nin söylemiş olduğu gibi onları dinlemedi."],["14","Yahve Moşe'ye şöyle dedi, “Firavun'un yüreği inatçıdır. Halkı salıvermeyi reddediyor."],["15","Sabahleyin Firavun'un yanına gidin. İşte, o suya çıkıyor. Onu karşılamak için nehrin kıyısında duracaksın. Yılana çevrilmiş değneği eline alacaksın."],["16","Ona diyeceksiniz ki, 'İbraniler'in Tanrısı Yahve, 'Halkımın gitmesine izin ver, çölde bana hizmet etsinler' diyerek beni sana gönderdi. İşte, şimdiye kadar dinlemedin.”"],["17","Yahve şöyle diyor, “Bununla benim Yahve olduğumu bileceksin. İşte, ben elimdeki değneği ırmaktaki sulara vuracağım ve sular kana dönecekler."],["18","Irmakta bulunan balıklar ölecek, nehir kokacak. Mısırlılar ırmaktan su içmekten tiksinecekler.''"],["19","Yahve Moşe'ye şöyle dedi, “Aron'a de ki, 'Değneğini al ve elini Mısır'ın sularına, ırmaklarına, derelerine, havuzlarına ve bütün su birikintileri üzerine uzat da kan olsun. Bütün Mısır diyarında, hem ağaç kaplarda hem de taş kaplarda kan olacak.'”"],["20","Moşe ve Aron, Yahve'nin buyurduğu gibi yaptılar. Firavun'un ve hizmetkârlarının gözü önünde değneği kaldırdı ve ırmaktaki sulara vurdu ve ırmaktaki bütün sular kana döndü."],["21","Irmakta bulunan balıklar öldü. Irmak koktu. Mısırlılar ırmaktan su içemediler. Kan tüm Mısır diyarındaydı."],["22","Mısır'ın büyücüleri de yaptıkları büyülerle aynı şeyi yaptılar. Böylece Firavun'un yüreği katılaştı ve Yahve'nin söylediği gibi onları dinlemedi."],["23","Firavun dönüp evine gitti, ama bunu ciddiye bile almadı."],["24","Bütün Mısırlılar içecek su bulmak için nehrin çevresini kazdılar; çünkü nehrin suyunu içemiyorlardı."],["25","Yahve'nin nehri vurmasının üzerinden yedi gün geçti."]],8:[["1","Yahve Moşe'ye şöyle konuştu, “Firavun'un yanına git ve ona söyle, 'Yahve şöyle diyor, Halkımın gitmesine izin ver de bana hizmet etsinler."],["2","Eğer onların gitmesine izin vermeyi reddedersen, işte, bütün sınırlarını kurbağalarla vuracağım."],["3","Irmak kurbağalarla dolup taşacak, kurbağalar yukarı çıkıp evinize, yatak odanıza, yatağınıza, hizmetkârlarının evine, halkınızın üzerine, fırınlarınıza ve hamur teknelerinize girecek."],["4","Kurbağalar hem senin, hem halkının, hem de bütün hizmetkârlarının üzerine çıkacak.'”"],["5","Yahve Moşe'ye şöyle dedi, “Aron'a de ki, ‘Değneğinle elini ırmakların, derelerin, havuzların üzerine uzat ve Mısır diyarının üzerine kurbağalar çıkart.'”"],["6","Aron elini Mısır suları üzerine uzattı ve kurbağalar çıkıp Mısır diyarını kapladılar."],["7","Büyücüler de büyüleriyle aynı şeyi yaptılar ve Mısır diyarı üzerine kurbağaları getirdiler."],["8","Bunun üzerine Firavun Moşe'yle Aron'u çağırıp şöyle dedi, “Yahve'ye yalvarın da kurbağaları benden ve halkımdan uzaklaştırsın. Ben de Yahve'ye kurban kesmeleri için halkın gitmesine izin vereceğim.”"],["9","Moşe Firavun'a şöyle dedi, “Kurbağaların senden ve evlerinden yok edilmesi ve yalnızca ırmakta kalması için senin, hizmetkârların ve halkın için dua etmem için bir zaman kararlaştırma onurunu sana veriyorum.”"],["10","Firavun, “Yarın” dedi. Moşe şöyle dedi, “Sözün uyarınca olsun, ta ki, Tanrımız Yahve gibisinin olmadığını bilesin."],["11","Kurbağalar senden, evlerinden, hizmetkârlarından ve halkından ayrılacak. Yalnızca ırmakta kalacaklar.”"],["12","Moşe ile Aron Firavun'un yanından ayrıldılar. Moşe, Firavun'a getirdiği kurbağalar hakkında Yahve'ye feryat etti."],["13","Yahve Moşe'nin sözüne göre yaptı ve evlerde, avlularda ve kırlarda kurbağalar öldü."],["14","Onları yığınlar halinde topladılar, ülke koktu."],["15","Ama Firavun ara verildiğini görünce yüreğini katılaştırdı ve Yahve'nin söylediği gibi onları dinlemedi."],["16","Yahve Moşe'ye şöyle dedi, “Aron'a de ki, 'Değneğini uzat ve yerin toprağına vur ki, bütün Mısır'da bit olsun.'”"],["17","Onlar da öyle yaptılar ve Aron değneğiyle elini uzattı ve yerin toprağına vurdu. İnsanların ve hayvanların üzerinde bit vardı. Mısır diyarında yerin bütün tozu bit oldu."],["18","Büyücüler büyüleriyle bit yapmaya çalıştılar ama başaramadılar. İnsanda ve hayvanda bit vardı."],["19","Bunun üzerine büyücüler Firavun'a, “Bu, Tanrı'nın parmağıdır” dediler. Ama Firavun'un yüreği katılaştı ve Yahve'nin söylediği gibi onları dinlemedi."],["20","Yahve Moşe'ye şöyle dedi, “Sabah erkenden kalk ve Firavun'un huzuruna çık. İşte, o, suya çıkıyor ve ona de ki, 'Yahve şöyle diyor, Halkımın gitmesine izin ver ki, bana hizmet etsinler."],["21","Yoksa halkımın gitmesine izin vermezsen, işte, senin, hizmetkârlarının, halkının ve evlerinin üzerine sinek sürüleri göndereceğim. Mısırlılar'ın evleri ve bulundukları toprak sinek sürüleriyle dolu olacak."],["22","O gün halkımın yaşadığı Goşen diyarını, orada sinek sürüsü olmasın diye ayıracağım, ta ki, benim yeryüzünde Yahve olduğumu bilesin."],["23","Kendi halkımla senin halkın arasına bölme koyacağım. Bu belirti yarın gerçekleşecek.'”"],["24","Yahve öyle yaptı. Firavun'un evine ve hizmetkârlarının evlerine korkunç sinek sürüleri geldi. Bütün Mısır diyarında sinek sürüleri yüzünden ülke harap oldu."],["25","Firavun, Moşe'yle Aron'u çağırıp, “Gidin, ülkede Tanrınız'a kurban kesin” dedi."],["26","Moşe şöyle dedi, “Böyle yapmak uygun değil. Çünkü Mısırlılar için iğrenç olanı Tanrımız Yahve'ye kurban edeceğiz. İşte, Mısırlılar için iğrenç olanı onların gözleri önünde kurban edersek, bizi taşlamazlar mı?"],["27","Çölde üç günlük yol gideceğiz ve Tanrımız Yahve'nin bize buyuracağı gibi kurban keseceğiz.”"],["28","Firavun şöyle dedi, “Çölde Tanrınız Yahve'ye kurban kesmeniz için sizin gitmenize izin vereceğim, ama çok uzağa gitmeyeceksiniz. Benim için dua edin.”"],["29","Moşe şöyle dedi, “İşte, yanından çıkıyorum. Yarın sinek sürülerinin Firavun'dan, hizmetkârlarından ve halkından uzaklaşması için Yahve'ye dua edeceğim. Yalnız Firavun Yahve'ye kurban kesmek için halkın gitmesine izin vermeyerek bir daha hilekârlık yapmasın.”"],["30","Moşe Firavun'un yanından çıkıp Yahve'ye dua etti."],["31","Yahve Moşe'nin sözüne göre yaptı ve Firavun'un, hizmetkârlarının ve halkının üzerinden sinek sürülerini uzaklaştırdı. Bir tane bile kalmadı."],["32","Firavun bu kez de yüreğini katılaştırdı ve halkın gitmesine izin vermedi."]],9:[["1","Bunun üzerine Yahve Moşe'ye şöyle dedi: “Firavun'un yanına git ve ona şunu söyle: 'İbraniler'in Tanrısı Yahve şöyle dedi: Halkımı salıver de bana hizmet etsinler."],["2","Çünkü onları salıvermeyi reddedip onları daha tutarsan,"],["3","işte, Yahve'nin eli çok ağır bir salgınla kırdaki hayvanlarınızın, atlarınızın, eşeklerinizin, develerinizin, sığırlarınızın ve davarlarınızın üzerindedir."],["4","Yahve İsrael'in hayvanları ile Mısır'ın hayvanları arasında ayrım yapacak. İsrael'in çocuklarına ait olanlardan hiçbiri ölmeyecek.'”"],["5","Yahve belli bir zaman belirleyip şöyle dedi: “Yahve yarın ülkede bu işi yapacak.”"],["6","Yahve ertesi gün o şeyi yaptı. Mısır'ın bütün hayvanları öldü, ama İsrael'in çocuklarının hayvanlarından biri bile ölmedi."],["7","Firavun adam gönderdi ve işte, İsrael'in çocuklarının tek bir hayvanı bile ölmemişti. Ancak Firavun'un yüreği inatçıydı ve halkın gitmesine izin vermedi."],["8","Yahve Moşe ve Aron'a şöyle dedi: “Ocak külünden avuç dolusu alın ve Moşe onu Firavun'un gözü önünde havaya saçsın."],["9","Bütün Mısır diyarı üzerinde ince bir toz haline gelecek, bütün Mısır diyarında insanlarda ve hayvanlarda irinli çıbanlar çıkacak.”"],["10","Ocak külünü alıp Firavun'un huzuruna çıktılar. Moşe onu havaya doğru serpti, insanda ve hayvanda irinli çıbanlar oldu."],["11","Büyücüler çıbanlardan dolayı Moşe'nin önünde duramadılar. Çünkü büyücülerin ve bütün Mısırlılar'ın üzerinde çıbanlar vardı."],["12","Yahve Firavun'un yüreğini katılaştırdı ve Yahve'nin Moşe'ye söylemiş olduğu gibi Firavun onları dinlemedi."],["13","Yahve Moşe'ye şöyle dedi: “Sabah erkenden kalk, Firavun'un huzuruna çık ve ona söyle: İbraniler'in Tanrısı Yahve şöyle diyor: Halkımı salıver de bana hizmet etsinler."],["14","Bu kez bütün belalarımı yüreğine, görevlilerine ve halkına göndereceğim, öyle ki, bütün yeryüzünde benim gibisinin olmadığını bilesin."],["15","Çünkü şimdi elimi uzatmış olsaydım, seni ve halkını vebayla vururdum, sen de yeryüzünden kesilip koparılırdın."],["16","Ama aslında ben seni bunun için, adım tüm yeryüzünde duyurulsun diye, sana gücümü göstermek için ayakta tuttum."],["17","Çünkü hâlâ halkıma karşı kendini yüceltiyorsun ve onların gitmesine izin vermiyorsun."],["18","İşte, yarın bu zamanlarda Mısır'da kurulduğu günden bu yana görülmemiş derecede şiddetli bir dolu yağdıracağım."],["19","Bu nedenle şimdi bütün hayvanlarının ve kırdaki tüm hayvanlarının barınağa alınmasını buyur. Kırda bulunan ve eve getirilmeyen her insan ve hayvanın üzerine dolu yağacak ve onlar ölecekler.'”"],["20","Firavun'un hizmetkârları arasında Yahve'nin sözünden korkanlar, hizmetçilerini ve hayvanlarını evlerine kaçırdılar."],["21","Yahve'nin sözüne saygı göstermeyen, hizmetçilerini ve hayvanlarını kırda bıraktı."],["22","Yahve Moşe'ye şöyle dedi: “Elini gökyüzüne doğru uzat ki, bütün Mısır diyarında, insanların, hayvanların ve Mısır diyarındaki bütün kır otlarının üzerine dolu yağsın.”"],["23","Moşe değneğini göklere doğru uzattı ve Yahve gök gürültüsü ve dolu gönderdi ve yeryüzüne yıldırım düştü. Yahve Mısır topraklarına dolu yağdırdı."],["24","Böylece çok şiddetli dolu vardı ve doluyla karışık şimşekler çaktı, Mısır'ın ulus haline gelmesinden bu yana bunun gibisi olmamıştı."],["25","Dolu, Mısır'ın her yerinde, insan olsun hayvan olsun, kırdaki her şeyi vurdu, dolu kırdaki her bitkiyi vurdu ve kırın her ağacını kırdı."],["26","Yalnızca İsrael'in çocuklarının bulunduğu Goşen diyarında dolu yoktu."],["27","Firavun Moşe'yle Aron'u çağırıp onlara şöyle dedi: “Bu sefer günah işledim. Yahve doğrudur, ben ve halkım kötüyüz."],["28","Yahve'ye dua edin, çünkü güçlü gök gürültüsü ve dolu yetti. Gitmenize izin vereceğim ve artık durmayacaksınız.”"],["29","Moşe ona şöyle dedi: “Kentten çıkar çıkmaz ellerimi Yahve'ye açacağım. Gök gürlemeleri kesilecek ve artık dolu olmayacak, ta ki, yeryüzünün Yahve'ye ait olduğunu bilesin."],["30","Ama sana ve hizmetkârlarına gelince, Yahve Tanrı'dan henüz korkmadığınızı biliyorum.”"],["31","Keten ve arpa vuruldu, çünkü arpa olgunlaşmış, keten de çiçek açmıştı."],["32","Ama buğday ve çavdar henüz büyümediğinden zarar görmemişti."],["33","Moşe Firavun'un yanından kentten çıktı ve ellerini Yahve'ye açtı. Gök gürültüsü ve dolu kesildi ve yeryüzünde yağmur dindi."],["34","Firavun yağmurun, dolunun ve gök gürültüsünün dindiğini görünce, daha da günah işledi ve hem kendisi, hem de hizmetkârları yüreklerini katılaştırdı."],["35","Firavun'un yüreği katılaştı ve Yahve'nin Moşe aracılığıyla söylemiş olduğu gibi İsrael'in çocuklarının gitmesine izin vermedi."]],10:[["1","Yahve Moşe'ye şöyle dedi: “Firavun'un yanına git, belirtilerimi aralarında göstermek için onun ve hizmetkârlarının yüreğini katılaştırdım."],["2","Mısır'a neler yaptığımı, onların arasında yaptığım belirtilerimi oğluna ve oğlunun oğlunun duyacağı şekilde anlat, öyle ki, benim Yahve olduğumu bilesiniz.”"],["3","Moşe ile Aron Firavun'un yanına gidip ona şöyle dediler: “İbraniler'in Tanrısı Yahve şöyle diyor: 'Benim önümde alçakgönüllü olmayı ne zamana dek reddedeceksin? Halkımın gitmesine izin ver ki, bana hizmet etsinler."],["4","Yoksa halkımın gitmesine izin vermezsen, işte, yarın ülkene çekirgeler getireceğim."],["5","Çekirgeler yeryüzünü kaplayacak, öyle ki kimse yeryüzünü göremeyecek. Doludan size kurtulmuş, artakalan yiyecekleri ve kırda sizin için büyüyen her ağacı yiyecekler."],["6","Senin evin, tüm hizmetkârlarının evleri ve tüm Mısırlılar'ın evleri, yeryüzünde bulundukları günden bugüne dek ne babaların ne de balarının babalarının görmediği şekilde dolacak.'” Dönüp Firavun'un yanından çıktı."],["7","Firavun'un hizmetkârları ona, “Bu adam bize ne zamana dek tuzak olacak?” dediler. “Adamları bırak gitsinler de Tanrıları Yahve'ye hizmet etsinler. Mısır'ın harap olduğunu hala bilmiyor musun?”"],["8","Moşe ile Aron tekrar Firavun'un yanına getirildiler. Firavun onlara şöyle dedi: “Gidin, Tanrınız Yahve'ye hizmet edin, ama gidecek olanlar kimlerdir?”"],["9","Moşe, “Gençlerimizle, yaşlılarımızla gideceğiz” dedi. “Oğullarımızla, kızlarımızla, davarlarımızla, sığırlarımızla gideceğiz. Çünkü Yahve için bayram yapacağız.”"],["10","O onlara şöyle dedi: “Eğer sizi çocuklarınızla birlikte bırakırsam Yahve sizinle olsun! Bakın, kötülük apaçık önünüzdedir."],["11","Öyle olmaz! Ey erkekler, şimdi gidin ve Yahve'ye hizmet edin, çünkü istediğiniz şey de bu!” Sonra onlar Firavun'un huzurundan kovuldular."],["12","Yahve Moşe'ye şöyle dedi: “Çekirgeler için elini Mısır toprakları üzerine uzat da Mısır topraklarına çıksınlar ve diyarın bütün otlarını, doludan arta kalanları yesinler.”"],["13","Moşe değneğini Mısır ülkesinin üzerine uzattı. Yahve bütün gün ve bütün gece ülkeye doğu rüzgârı getirdi. Sabah olduğunda doğu rüzgârı da çekirgeleri getirdi."],["14","Çekirgeler bütün Mısır topraklarına yayılıp Mısır'ın bütün sınırlarına kondu. Çok feciydiler. Onlardan önce onlar gibi çekirge olmamıştı, bir daha da olmayacaktır."],["15","Çünkü bütün yeryüzünü kapladılar, öyle ki, ülke karardı ve dolunun bıraktığı tüm otları ve ağaçlarda kalan tüm meyveleri yediler. Bütün Mısır diyarında kırın ağacında ve otunda hiçbir yeşillik kalmadı."],["16","Firavun aceleyle Moşe'yle Aron'u çağırıp şöyle dedi: “Tanrınız Yahve'ye ve size karşı günah işledim."],["17","Şimdi lütfen günahımı bir kez daha bağışla ve bu ölümü benden uzaklaştırması için de Tanrın Yahve'ye dua et.”"],["18","Moşe Firavun'un yanından çıkıp Yahve'ye dua etti."],["19","Yahve çok kuvvetli bir batı rüzgârı göndererek çekirgeleri alıp Kızıldeniz'e sürdü. Mısır'ın bütün sınırlarında tek bir çekirge kalmadı."],["20","Ancak Yahve Firavun'un yüreğini katılaştırdı ve İsrael'in çocuklarının gitmesine izin vermedi."],["21","Yahve Moşe'ye şöyle dedi: “Elini göğe doğru uzat ki, Mısır diyarında karanlık olsun, üstelik hissedilebilen bir karanlık olsun.”"],["22","Moşe elini gökyüzüne doğru uzattı, bütün Mısır topraklarında üç gün boyunca koyu bir karanlık vardı."],["23","Üç gün boyunca birbirlerini görmediler ve kimse yerinden kalkmadı, ancak bütün İsrael'in çocuklarının evlerinde ışık vardı."],["24","Firavun Moşe'yi çağırıp şöyle dedi: “Gidin, Yahve'ye hizmet edin. Yalnız davarlarınız ve sığırlarınız geride kalsın. Küçükleriniz de sizinle birlikte gitsin.”"],["25","Moşe şöyle dedi: “Tanrımız Yahve'ye kurban sunmamız için bize kurbanlar ve yakmalık sunular da vermelisin."],["26","Hayvanlarımız da bizimle birlikte gidecek. Geride tek bir toynak bile kalmayacak. Çünkü Tanrımız Yahve'ye hizmet etmek için onlardan almalıyız. Oraya varıncaya dek Yahve'ye neyle hizmet etmemiz gerektiğini bilmiyoruz.”"],["27","Ama Yahve Firavun'un yüreğini katılaştırdı ve o onların gitmesine izin vermedi."],["28","Firavun ona, “Benden uzak dur!” dedi. “Dikkatli ol, artık yüzümü görme. Çünkü yüzümü gördüğün gün öleceksin!”"],["29","Moşe, “İyi dedin.” dedi. “Bir daha yüzünü görmeyeceğim.”"]],11:[["1","Yahve Moşe'ye şöyle dedi: “Firavun'un ve Mısır'ın başına bir bela daha getireceğim, ondan sonra gitmenize izin verecek. Gitmenize izin verdiğinde, sizi kesinlikle toplu olarak kovacaktır."],["2","Şimdi halkın kulağına söyle, her adam kendi komşusundan, her kadın da kendi komşusundan gümüş, altın mücevherler istesin.''"],["3","Yahve Mısırlılar'ın gözünde halka lütuf verdi. Üstelik, Moşe denen adam Mısır diyarında Firavun'un hizmetkârlarının ve halkın gözünde çok büyüktü."],["4","Moşe şöyle dedi: “Yahve şöyle diyor: 'Gece yarısına doğru Mısır'ın ortasına çıkacağım."],["5","Tahtında oturan Firavun'un ilk doğanından, değirmen ardındaki cariyenin ilk doğanına kadar, Mısır ülkesindeki bütün ilk doğanlar, hayvanların ilk doğanları ölecek."],["6","Bütün Mısır diyarında benzeri olmamış, bir daha da olmayacak büyük bir feryat kopacak."],["7","Ancak Yahve'nin Mısırlılar ile İsraelliler arasında ayrım yaptığını bilesiniz diye, insandan hayvana dek, İsrael'in çocuklarından hiçbirine karşı bir köpek havlamayacak, dilini bile oynatmayacak."],["8","Bütün bu hizmetkârların aşağıya yanıma gelip önümde eğilecekler ve şöyle diyecekler: “Sen ve ardından gelen bütün halkla birlikte çıkın.” ve ben ondan sonra çıkacağım.'” Firavun'un yanından kızgın bir öfkeyle çıktı."],["9","Yahve Moşe'ye, “Mısır ülkesinde harikalarım çoğalsın diye Firavun seni dinlemeyecek” dedi."],["10","Moşe ve Aron tüm bu harikaları Firavun'un önünde yaptılar, ama Yahve Firavun'un yüreğini katılaştırdı ve İsrael'in çocuklarının ülkesinden çıkmasına izin vermedi."]],12:[["1","Yahve Mısır'da Moşe ve Aron'la konuşup şöyle dedi,"],["2","“Bu ay sizin için ayların başlangıcı olacak. Bu sizin için yılın ilk ayı olacak."],["3","Bütün İsrael topluluğuna konuşup söyleyin, 'Bu ayın onuncu günü, her biri kendilerine bir kuzu, atalarının evlerine göre, ev halkına bir kuzu alacak."],["4","Eğer ev halkı bir kuzu için çok küçükse, o zaman o ve evinin yanındaki komşusu, canların sayısına göre bir tane alacaklar. Kuzu hesabını herkesin yiyebileceği kadarıyla yapacaksınız."],["5","Kuzunuz kusursuz, bir yaşında erkek olacak. Onu koyunlardan ya da keçilerden alacaksınız."],["6","Onu aynı ayın on dördüncü gününe dek saklayacaksınız. İsrael halkının bütün topluluğu akşam onu öldürecekler."],["7","Kanın bir kısmını alıp onu içlerinde yiyecekleri evlerin iki kapı sövesine ve üst eşiği üzerine sürecekler."],["8","O gece ateşte kızartılmış eti mayasız ekmekle yiyecekler. Onu acı otlarla yiyecekler."],["9","Onu ne çiğ, ne de suda haşlanmış yiyin, yalnızca başı, bacakları ve iç kısımlarıyla birlikte ateşte kızarmış olarak yiyin."],["10","Sabaha kadar ondan hiçbir şey kalmayacak, ondan sabaha kadar artakalanı ateşle yakacaksın."],["11","Eti şu şekilde yiyeceksiniz: Kuşağınız belinizde, çarıklarınız ayağınızda ve değneğiniz elinizde olacak. Onu acele ederek yiyeceksiniz, bu, Yahve'nin Pesah'ıdır."],["12","Çünkü o gece Mısır diyarından geçeceğim ve Mısır diyarında insan olsun hayvan olsun bütün ilk doğanları vuracağım. Mısır'ın bütün ilâhlarını yargılayacağım. Ben Yahve'yim."],["13","Bulunduğunuz evlerin kanı sizin için bir işaret olacak. Kanı görünce üzerinizden geçeceğim ve Mısır diyarını vurduğumda üzerinizde sizi yok edecek bela olmayacak."],["14","Bugün sizin için bir anma günü olacak. Onu Yahve'ye bir bayram olarak tutacaksınız. Sonsuza dek süren bir kuralla onu kuşaklarınız boyunca bayram olarak tutacaksınız.'”"],["15","“'Yedi gün mayasız ekmek yiyeceksiniz. Hatta ilk gün evinizden mayayı çıkaracaksınız, çünkü kim birinci günden yedinci güne kadar mayalı ekmek yerse, o can İsrael'den atılacaktır."],["16","İlk gün sizin için kutsal bir toplantı olacak, yedinci gün de kutsal bir toplantı olacaktır. Herkesin yeme zorunluluğu dışında, ki yalnızca bunu yapabilirler, onlarda başka hiçbir iş yapılmayacaktır."],["17","Mayasız Ekmek Bayramı'nı tutacaksınız, çünkü aynı gün ordularınızı Mısır diyarından çıkardım. Bu nedenle bu günü kuşaklarınız boyunca daima süren bir kuralla tutacaksınız."],["18","Birinci ayın on dördüncü günü akşamından, yirmi birinci günü akşamına kadar mayasız ekmek yiyeceksiniz."],["19","Evlerinizde yedi gün boyunca maya bulunmayacak, çünkü kim mayalı olanı yerse, ister yabancı olsun ister ülkede doğmuş olsun, o can İsrael topluluğundan atılacaktır."],["20","Mayalı hiçbir şey yemeyeceksiniz. Yaşadığınız her yerde mayasız ekmek yiyeceksiniz.'”"],["21","Bunun üzerine Moşe İsrael'in bütün ihtiyarlarını çağırıp onlara şöyle dedi: “Ailenize göre kendiniz için kuzular çekip alın ve Pesah kurbanını kesin."],["22","Bir demet mercanköşkotu alıp leğendeki kana batıracaksınız, leğendeki kanla üst söveye ve iki kapı eşiğine çalacaksınız. Hiçbiriniz sabaha kadar evinin kapısından çıkmasın."],["23","Çünkü Yahve Mısırlılar'ı vurmak için geçecek. Yahve üst eşik üzerindeki ve iki kapı sövesindeki kanı görünce kapının üzerinden geçecek ve yok edicinin evlerinize gelip sizi vurmasına izin vermeyecek."],["24","Kendiniz ve oğullarınız için bir kural olarak bu şeyi daima tutacaksınız."],["25","Böyle olacak, Yahve'nin söz verdiği gibi size vereceği ülkeye geldiğiniz zaman bu hizmeti tutacaksınız."],["26","Böyle olacak, çocuklarınız size, 'Bu hizmet ne demektir?' diye sorduklarında,"],["27","şöyle diyeceksiniz: 'Bu, Mısır'da İsrael'in çocuklarının evlerinin üzerinden geçen, Yahve'nin Pesah kurbanıdır, O Mısırlılar'ı vurduğunda evlerimizi esirgedi.'” Halk başlarını eğip tapındı."],["28","İsrael'in çocukları gidip öyle yaptılar, Yahve'nin Moşe ve Aron'a buyurduğu gibi öyle yaptılar."],["29","Gece yarısı Yahve, tahtında oturan Firavun'un ilk doğanından, zindandaki tutsağın ilk doğanına kadar Mısır diyarında bütün ilk doğanları ve hayvanların ilk doğanlarını vurdu."],["30","Firavun'un kendisi, bütün hizmetkârları ve bütün Mısırlılar geceleyin kalktılar; ve Mısır'da büyük bir feryat vardı, çünkü içinde ölü olmayan ev yoktu."],["31","Gece Moşe'yle Aron'u çağırıp şöyle dedi: “Kalkın, hem siz hem de İsrael'in çocukları halkımın arasından çıkın. Gidin, söylediğiniz gibi Yahve'ye hizmet edin!"],["32","Söylediğiniz gibi davarlarınızı ve sığırlarınızı alın ve gidin. Beni de kutsayın!”"],["33","Mısırlılar, “Hepimiz ölü insanlarız” dediklerinden, onları bir an önce ülkeden göndermek için halka acil çağrıda bulundular."],["34","Halk hamurlarını daha mayalanmadan aldılar, hamur tekneleri giysilerine sarılmış omuzlarındaydı."],["35","İsrael'in çocukları Moşe'nin sözüne göre yaptılar ve Mısırlılar'dan gümüş takılar, altın takılar ve giysiler istediler."],["36","Yahve Mısırlılar'ın gözünde halka lütuf verdi, böylece onlar da istediklerini aldılar. Mısırlılar'ı yağmaladılar."],["37","İsrael'in çocukları, çocukların yanı sıra yaklaşık altı yüz bin kişi yaya olarak Ramses'ten Sukkot'a doğru yola çıktılar."],["38","Davarlar, sığırlar ve çok sayıda hayvanla karışık bir kalabalık da onlarla birlikte yola çıktı."],["39","Mısır'dan getirdikleri hamurdan mayasız pideler pişirdiler, çünkü mayalanmamıştı, çünkü Mısır'dan kovuldular, bekleyemediler ve kendilerine yiyecek hazırlamamışlardı."],["40","İsrael'in çocuklarının Mısır'da yaşadığı süre dört yüz otuz yıldı."],["41","Dört yüz otuz yılın sonunda Yahve'nin bütün orduları Mısır diyarından aynı günde çıktılar."],["42","Onları Mısır diyarından çıkardığı için Yahve için çok kutlanması gereken bir gecedir. Bu, İsrael'in çocuklarının kuşaklar boyunca çokça kutlayacağı, Yahve'nin o gecesidir."],["43","Yahve Moşe'yle Aron'a şöyle dedi: “Pesah'ın kuralı budur. Hiçbir yabancı ondan yemeyecek."],["44","Ancak para karşılığında satın alınan her hizmetkâr, sünnet ettirildikten sonra ondan yiyecektir."],["45","Yabancı ve ücretli hizmetçi ondan yemeyecektir."],["46","Bir evde yenmeli. Etin hiçbirini evin dışına taşımayacaksınız. Kemiklerinden hiçbirini kırmayacaksınız."],["47","Bütün İsrael topluluğu onu tutacaktır."],["48","Yanında garip olarak yaşayan bir yabancı Yahve'ye Pesah tutmak isterse, onun bütün erkekleri sünnet edilsinler, ondan sonra yaklaşıp onu tutsun. O ülkede doğmuş biri gibi olacak, ancak sünnetsiz hiç kimse ondan yemeyecektir."],["49","Kendi evinizde doğan ve aranızda garip olarak yaşayan yabancı için yasa aynı olacaktır.”"],["50","Bütün İsrael'in çocukları böyle yaptılar. Yahve Moşe ve Aron'a nasıl buyurduysa onlar da öyle yaptılar."],["51","Aynı o günde Yahve İsrael'in çocuklarını ordularıyla Mısır diyarından çıkardı."]],13:[["1","Yahve Moşe'ye şöyle dedi:"],["2","“İsrael'in çocukları arasında insan olsun hayvan olsun rahmi açan tüm ilk doğanları bana ayır. O benimdir.”"],["3","Moşe halka şöyle dedi: “Mısır'dan, esaret evinden çıktığınız bu günü hatırlayın. Çünkü Yahve elinin gücüyle sizi bu yerden çıkardı. Mayalı ekmek yenilmeyecek."],["4","Bugün siz Aviv ayında çıkıyorsunuz."],["5","Böyle olacak, Yahve seni atalarına vereceğine dair ant içtiği Kenan, Hitit, Amor, Hiv ve Yevus topraklarına, süt ve bal akan ülkeye getirdiği zaman, bu ay bu hizmeti tutacaksın."],["6","Yedi gün mayasız ekmek yiyeceksin, yedinci gün Yahve'ye bayram olacak."],["7","Yedi gün boyunca mayasız ekmek yenilecek ve sende mayalı ekmek görülmeyecek. Bütün sınırlarında, sende maya görülmeyecek."],["8","O gün oğluna, 'Mısır'dan çıktığımda Yahve'nin benim için yaptığı şey içindir' diyeceksin."],["9","Bu, elinde bir işaret, gözlerinin arasında bir anma olacak, ta ki, Yahve'nin yasası ağzında olsun. Çünkü Yahve güçlü eliyle seni Mısır'dan çıkardı."],["10","Bu nedenle bu kutsal kuralı her yıl mevsiminde tutacaksın.”"],["11","“Böyle olacak, Yahve size ve atalarınıza ant içtiği gibi sizi Kenan diyarına götürüp orayı size vereceği zaman,"],["12","rahmi açan her şeyi, sana ait olan hayvanın ilk doğanlarını Yahve'ye ayıracaksın. Erkekler Yahve'nin olacak."],["13","Eşeğin her ilk doğanı için bir kuzu fidye vereceksin. Eğer fidye veremeyeceksen o zaman onun boynunu kıracaksın. Oğullarının arasında insanın ilk doğanlarının hepsinin fidyesini vereceksin."],["14","Böyle olacak, oğlun ileride sana, 'Bu nedir?' diye sorduğunda, ona diyeceksin ki, 'Yahve bizi Mısır'dan, esaret evinden elinin gücüyle çıkardı."],["15","Firavun inatla bizi bırakmayı reddedince, Yahve Mısır'da hem insanın hem de hayvanların ilk doğanlarını öldürdü. Bu nedenle rahmi açan bütün erkekleri Yahve'ye kurban ediyorum, ancak oğullarımın ilk doğanlarının hepsi için fidye veriyorum.'"],["16","Bu, elinde bir işaret, gözlerinin arasında simge olacak, Çünkü Yahve elinin gücüyle bizi Mısır'dan çıkardı.”"],["17","Firavun halkı salıverdiğinde, orası daha yakın olduğu halde Tanrı onları Filist ülkesinin yolundan götürmedi Çünkü Tanrı şöyle dedi: “Belki halk savaşı görünce fikir değiştirip Mısır'a döner.”"],["18","Ama Tanrı halkı Kızıldeniz kıyısındaki çöl yolundan götürdü. İsrael'in çocukları Mısır diyarından silahlı olarak çıktılar."],["19","Moşe, “Tanrı sizi mutlaka ziyaret edecek ve kemiklerimi buradan sizinle birlikte taşıyacaksınız” diyerek İsrael'in çocuklarına ant içirdiği için Yosef'in kemiklerini de yanına aldı."],["20","Sukkot'tan yola çıkıp çölün kıyısındaki Etam'da konakladılar."],["21","Yahve gündüzleri bir bulut sütunu içinde önlerinden giderek onlara yol gösterdi, geceleyin de bir ateş sütunu içinde onlara ışık vererek gece gündüz yol alabilmeleri için önlerinden gidiyordu."],["22","Gündüzleri bulut sütunu, geceleyin de ateş sütunu halkın önünden ayrılmadı."]],14:[["1","Yahve Moşe'ye şöyle konuştu:"],["2","“İsrael halkına geri dönüp Pihahirot'un önünde, Migdol ile deniz arasında, Baal Sefon'un önünde kamp kurmalarını söyle. Onun karşısında, deniz kenarında kamp kuracaksınız."],["3","Firavun İsrael'in çocukları için, 'Onlar o diyarın içinde şaşkındırlar' diyecek. 'Çöl onları hapsetmiştir.’"],["4","Firavun'un yüreğini katılaştıracağım, o da onların peşine düşecek. Firavun ve onun bütün orduları üzerinde yücelik kazanacağım. Mısırlılar benim Yahve olduğumu bilecekler.” Öyle yaptılar."],["5","Mısır Kralı'na halkın kaçtığı söylendi. Firavun ile hizmetkârlarının yüreği halka karşı değişti ve dediler: “Biz ne yaptık da İsrael'i bize hizmet etmekten salıverdik?”"],["6","Arabasını hazırlayıp ordusunu da yanına aldı."],["7","Seçme altı yüz savaş arabasını ve Mısır'ın bütün savaş arabalarını, hepsinin komutanlarıyla birlikte aldı."],["8","Yahve Mısır Kralı Firavun'un yüreğini katılaştırdı ve İsrael'in çocuklarının peşine düştü. Çünkü İsrael'in çocukları yüksek elle dışarı çıkmışlardı."],["9","Mısırlılar onların peşine düştü. Firavun'un bütün atları ve savaş arabaları, atlıları ve ordusu, deniz kenarında, Pihahirot'un yanında, Baal Sefon'un önünde kamp kurarken onlara yetiştiler."],["10","Firavun yaklaşınca İsrael'in çocukları gözlerini kaldırdılar, işte, Mısırlılar onların peşinden yürüyorlardı ve çok korktular. İsrael'in çocukları Yahve'ye feryat ettiler."],["11","Moşe'ye şöyle dediler, “Mısır'da mezar olmadığı için bizi çölde ölmeye mi getirdin? Bizi Mısır'dan çıkarmakla bize neden böyle davrandın?"],["12","Mısır'da sana, 'Bizi rahat bırak, Mısırlılar'a hizmet edelim' diye söylediğimiz söz bu değil mi? Çünkü çölde ölmektense Mısırlılar'a hizmet etmek bizim için daha iyi olurdu.”"],["13","Moşe halka şöyle dedi: “Korkmayın. Sakin durun ve bugün sizin için gerçekleştireceği Yahve'nin kurtarışını görün. Çünkü bugün gördüğünüz Mısırlılar'ı bir daha asla görmeyeceksiniz."],["14","Yahve sizin için savaşacak, siz de sakin olacaksınız.”"],["15","Yahve Moşe'ye şöyle dedi: “Neden bana feryat ediyorsun? İsrael'in çocuklarına ileri gitmelerini söyle."],["16","Değneğini kaldır, elini denizin üzerine uzat ve onu ayır. Sonra İsrael'in çocukları denizin ortasına kuru yerden girecekler."],["17","İşte, ben Mısırlılar'ın yüreklerini katılaştıracağım ve onlar da onların arkasından girecekler. Firavun'un, bütün ordularının, savaş arabalarının ve atlılarının önünde kendime yücelik kazandıracağım."],["18","Firavun'un, savaş arabalarının ve atlılarının önünde yücelik kazandığımda, Mısırlılar benim Yahve olduğumu bilecekler.”"],["19","İsrael ordugâhının önünden giden Tanrı'nın meleği yer değiştirip arkalarına gitti. Bulut sütunu da önlerinden yer değiştirip arkalarında durdu."],["20","Mısır ordugâhıyla İsrael ordugâhının arasına geldi. Bulut ve karanlık vardı ama geceyi aydınlatıyordu. Bütün gece biri ötekinin yanına yaklaşmadı."],["21","Moşe elini denizin üzerine uzattı ve Yahve bütün gece kuvvetli doğu rüzgârıyla denizi geri döndürdü, denizi karaya çevirdi ve sular ayrıldı."],["22","İsrael'in çocukları kuru yerden denizin ortasına girdiler. Sular sağlarında ve sollarında onlara duvar oldu."],["23","Mısırlılar onları takip ettiler, Firavun'un bütün atları, savaş arabaları ve atlıları arkalarından denizin ortasına girdiler."],["24","Sabah nöbetinde Yahve ateş ve bulut sütunundan Mısır ordusuna baktı ve Mısır ordusunu şaşkına çevirdi."],["25","Arabaların tekerleklerini çıkardı ve onları ağır bir şekilde sürdüler. Mısırlılar, “İsrael'in önünden kaçalım, çünkü Yahve onlar için Mısırlılar'a karşı savaşıyor!” dediler."],["26","Yahve Moşe'ye, “Elini denizin üzerine uzat” dedi, “Sular yeniden Mısırlılar'ın, savaş arabalarının ve atlılarının üzerine gelsin.”"],["27","Moşe elini denizin üzerine uzattı. Sabah olunca deniz yeniden eski gücüne döndü. Mısırlılar onun karşısında kaçtılar. Yahve Mısırlılar'ı denizin ortasında devirdi."],["28","Sular döndü ve savaş arabalarını, atlıları, arkalarından denize giren Firavun'un tüm ordusunu örttü. Onlardan biri bile kalmadı."],["29","Ancak İsrael'in çocukları denizin ortasındaki kuru toprakta yürüdüler, sular sağlarında ve sollarında onlara duvar oldu."],["30","Böylece Yahve o gün İsrael'i Mısırlılar'ın elinden kurtardı ve İsrael Mısırlılar'ın deniz kıyısında öldüğünü gördü."],["31","İsrael, Yahve'nin Mısırlılar'a yaptığı büyük işi gördü ve halk Yahve'den korktu. Yahve'ye ve hizmetkârı Moşe'ye inandılar."]],15:[["1","Bunun üzerine Moşe ile İsrael'in çocukları Yahve'ye bu ezgiyi söylediler ve şöyle dediler: “Yahve'ye ezgi söyleyeceğim, çünkü O görkemle zafer kazandı. Atı ve binicisini denize attı."],["2","Yahve benim gücüm ve ezgimdir. O benim kurtuluşum oldu. O benim Tanrım'dır ve O'nu öveceğim, babamın Tanrısı ve ben O'nu yücelteceğim."],["3","Yahve bir savaş adamıdır. Adı Yahve'dir."],["4","Firavun'un savaş arabalarını ve ordusunu denize attı. Seçme subayları Kızıldeniz'de battı."],["5","Derinler onları örttü. Taş gibi derinliklere indiler."],["6","Senin sağ elin, ey Yahve, kudrette yücedir. Senin sağ elin, ey Yahve, düşmanı parçalara ayırır."],["7","Heybetinin büyüklüğüyle sana karşı ayaklananları alt edersin. Gazabını gönderirsin. Onları anız gibi tüketir."],["8","Öfkenin soluğuyla sular yığıldılar. Seller yığın gibi dimdik durdu. Derinlikler denizin ortasında dondular."],["9","Düşman, 'Ben kovalayacağım' dedi. 'Yetişeceğim. Ganimeti paylaşacağım. Arzum onlarda yerine gelecek. Kılıcımı çekeceğim. Elim onları yok edecek.’"],["10","Sen rüzgârınla üfledin. Deniz onları örttü. Güçlü sularda kurşun gibi battılar."],["11","İlâhlar arasında senin gibi kim var, ey Yahve? Senin gibi kutsallıkta yüce, övgülerde heybetli, harikalar yapan kim var?"],["12","Sağ elini uzattın. Yer onları yuttu."],["13","“Sen kurtardığın halka sevgi dolu iyiliğinle rehberlik ettin. Gücünle onlara kutsal meskenine doğru yol gösterdin."],["14","Halklar duydu. Titriyorlar. Dehşetler Filist sakinlerini ele geçirdi."],["15","O zaman Edom ileri gelenleri dehşete düştüler. Moav'ın güçlü adamları titremeye başladı. Kenan'da oturanların tümü eriyip gitti."],["16","Üzerlerine korku ve dehşet indi. Senin halkın geçene kadar, ey Yahve, kendine satın aldığın halkın geçene kadar, kolunun büyüklüğünden taş gibi kesildiler."],["17","Onları içeri getireceksin, mirasın olan dağa, ey Yahve, kendine oturmak için yaptığın yere, ey Yahve, ellerinin kurduğu kutsal yerde onları dikeceksin."],["18","Yahve sonsuza dek hüküm sürecek.”"],["19","Çünkü Firavun'un atları savaş arabalarıyla ve atlılarıyla birlikte denize girdiler ve Yahve denizin sularını üzerlerine geri getirdi. Ama İsrael'in çocukları denizin ortasındaki kuru yerden yürüdüler."],["20","Aron'un kız kardeşi Peygamber Miryam eline bir tef aldı. Bütün kadınlar teflerle ve danslarla onun peşinden çıktılar."],["21","Miryam onlara şöyle yanıt verdi: “Yahve'ye ezgi söyleyin, çünkü O görkemle zafer kazandı. Atı ve binicisini denize attı.”"],["22","Moşe İsrael'i Kızıldeniz'den ileri götürdü ve Şur Çölü'ne çıktılar. Çölde üç gün gittiler ve su bulamadılar."],["23","Mara'ya vardıklarında Mara sularından içemediler. Çünkü onlar acıydı. Bu nedenle adına Mara denildi."],["24","Halk, “Ne içelim?” diye Moşe'ye karşı söylendiler."],["25","Sonra o Yahve'ye feryat etti. Yahve ona bir ağaç gösterdi, o da onu sulara attı ve sular tatlılaştı. Orada onlar için bir kural ve hüküm koydu. Onları orada sınadı."],["26","Şöyle dedi, “Tanrınız Yahve'nin sözünü dikkatle dinlerseniz, O'nun gözünde doğru olanı yaparsanız, buyruklarına dikkat ederseniz ve bütün kurallarına uyarsanız, Mısırlılar'ın üzerine koyduğum hastalıkların hiçbirini sizin üzerinize koymayacağım. Çünkü sana şifa veren Yahve benim.”"],["27","On iki su kaynağı ve yetmiş palmiye ağacının bulunduğu Elim'e geldiler. Orada suların kenarında kamp kurdular."]],16:[["1","İsrael'in çocuklarının bütün topluluğu Elim'den yola çıktılar ve Mısır diyarından ayrıldıktan sonraki ikinci ayın on beşinci günü, İsrael'in çocuklarının bütün topluluğu Elim ile Sina arasındaki Sin Çölü'ne geldiler."],["2","İsrael'in çocuklarının bütün topluluğu çölde Moşe'ye ve Aron'a karşı söylendiler."],["3","İsrael'in çocukları onlara şöyle dediler: “Keşke Mısır diyarında et kazanlarının başında oturduğumuzda, ekmeğimizi doyuncaya dek yediğimiz sırada Yahve'nin eliyle ölseydik. Çünkü bütün bu topluluğu açlıkla öldürmek için sen bizi bu çöle çıkardın.”"],["4","Bunun üzerine Yahve Moşe'ye şöyle dedi: “İşte, senin için gökten ekmek yağdıracağım ve halk çıkıp her gün bir günlük pay toplayacak, böylece yasama göre yürüyüp yürümeyeceklerini sınayacağım."],["5","Altıncı günde getirdiklerini hazırlayacaklar ve bu, günlük topladıklarının iki katı olacak.”"],["6","Moşe ile Aron bütün İsrael'in çocuklarına şöyle dediler: “Akşam, Yahve'nin sizi Mısır diyarından çıkardığını bileceksiniz."],["7","Sabah Yahve'nin görkemini göreceksiniz. Çünkü Yahve kendisine karşı söylenmenizi işitiyor. Biz kimiz ki, bize karşı söyleniyorsunuz?”"],["8","Moşe şöyle dedi: “Şimdi Yahve size akşamları yemeniz için et, sabahları da doymanız için ekmek verecek. Çünkü Yahve, kendisine karşı söylenmelerinizi işitiyor. Peki biz kimiz? Söylenmeleriniz bize karşı değil, Yahve'ye karşıdır.”"],["9","Moşe Aron'a şöyle dedi: “Bütün İsrael'in çocuklarının topluluğuna deyin ki, 'Yahve'ye yaklaşın, çünkü O sizin söylenmelerinizi duydu.'''"],["10","Aron bütün İsrael'in çocuklarının topluluğuyla konuşurken çöle doğru baktılar ve işte, Yahve'nin görkemi bulutta göründü."],["11","Yahve Moşe'ye şöyle dedi:"],["12","“İsrael'in çocuklarının söylenmelerini duydum. Onlara de ki, 'Akşam et yiyeceksiniz ve sabahleyin ekmekle doyacaksınız. O zaman benim Tanrınız Yahve olduğumu bileceksiniz.'”"],["13","Akşam bıldırcınlar çıkıp ordugâhı kapladı ve sabahleyin ordugâhın çevresine çiy serilmişti."],["14","Yere serilmiş çiy kaybolduğunda, işte, çölün yüzeyinde yerdeki kırağı kadar küçük, yuvarlak bir şey vardı."],["15","İsrael çocukları bunu görünce birbirlerine, “Bu nedir?” dediler. Çünkü ne olduğunu bilmiyorlardı. Moşe onlara şöyle dedi: “Bu, yemeniz için Yahve'nin size verdiği ekmektir."],["16","Yahve'nin buyurduğu şey şudur: 'Her biriniz yiyeceğine göre ondan toplayın. Her biriniz çadırında olanların sayısına göre bir omer, bir baş alacak.'”"],["17","İsrael'in çocukları da öyle yaptı. Bazıları daha çok, bazıları daha az topladı."],["18","Omerle ölçtüklerinde, çok toplayanın fazlası, az toplayanın da eksiği yoktu. Her biri yiyeceğine göre toplamıştı."],["19","Moşe onlara, “Sabaha kadar kimse ondan bırakmasın” dedi."],["20","Ne var ki Moşe'nin sözünü dinlemediler ve bazıları ondan sabaha kadar bıraktılar. Kurtlanıp koktu. Moşe de onlara öfkelendi."],["21","Herkes yiyeceğine göre sabahtan sabaha ondan topladılar. Güneş ısınınca erirdi."],["22","Altıncı gün her biri için iki omer olmak üzere iki kat ekmek topladılar. Topluluğun bütün önderleri gelip Moşe'ye bildirdiler."],["23","Onlara şöyle dedi: “Yahve'nin söylediği budur, 'Yarın kutsal dinlenme günü, Yahve için kutsal Şabat'dır. Pişirmek istediğinizi pişirin, haşlamak istediğinizi haşlayın. Arta kalanı da sabaha kadar saklamak üzere kendiniz için bir kenara koyun.'”"],["24","Moşe'nin buyurduğu gibi onu sabaha kadar bir kenara koydular, kokmadı, onda kurt da yoktu."],["25","Moşe, “Onu bugün yiyin” dedi, “Çünkü bugün Yahve için Şabat'dır. Bugün onu kırda bulamayacaksınız."],["26","Altı gün toplayacaksınız, ama yedinci gün Şabat'dır. O günde hiçbir şey bulunmayacak.”"],["27","Yedinci gün halktan bazıları toplamaya çıktı ama hiçbir şey bulamadılar."],["28","Yahve Moşe'ye şöyle dedi: “Buyruklarımı ve yasalarımı tutmayı ne zamana dek reddedeceksiniz?"],["29","İşte, Yahve size Şabat'ı verdiği için, altıncı günde size iki günlük ekmeğinizi veriyor. Herkes kendi yerinde kalsın. Yedinci günde kimse yerinden çıkmasın.”"],["30","Böylece halk yedinci gün dinlendi."],["31","İsrael evi onun adını Man koydu. Kişniş tohumu gibi beyazdı. Tadı da ballı yufkaya benziyordu."],["32","Moşe şöyle dedi: “Yahve'nin buyurduğu şey şudur: 'Mısır diyarından sizi çıkardığım zaman, çölde size yedirdiğim ekmeği görsünler diye bundan bir omer dolusu kuşaklarınız boyunca saklansın.'”"],["33","Moşe Aron'a, “Bir testi al, içine bir omer dolusu man koy” dedi, “Kuşaklar boyu saklanmak üzere onu Yahve'nin huzuruna koy.”"],["34","Yahve'nin Moşe'ye buyurduğu gibi Aron onu saklanmak üzere Tanıklığın önüne koydu."],["35","İsrael'in çocukları üzerinde yaşayanların bulunduğu bir diyara gelene dek kırk yıl boyunca man yediler."],["36","Bir omer efanın onda biridir."]],17:[["1","İsrael'in çocuklarının bütün topluluğu Yahve'nin buyruğu uyarınca Sin Çölü'nden yola çıkıp Refidim'de konakladı. Ancak halkın içeceği su yoktu."],["2","Bunun üzerine halk Moşe'yle tartışıp, “Bize içecek su ver” dediler. Moşe onlara şöyle dedi: “Neden benimle tartışıyorsunuz? Neden Yahve’yi sınıyorsunuz?”"],["3","Orada halk susamıştı. Bunun üzerine halk Moşe'ye karşı söylenip şöyle dediler: “Bizi, çocuklarımızı ve hayvanlarımızı susuzluktan öldürmek için neden bizi Mısır'dan çıkardın?”"],["4","Moşe Yahve'ye feryat edip, dedi: “Bu halka ne yapayım? Neredeyse beni taşlayacaklar.”"],["5","Yahve Moşe'ye şöyle dedi: “Halkın önünde yürü, İsrael'in ihtiyarlarını da yanına al ve Nil'e vurduğun değneği eline alıp git."],["6","İşte, ben Horev'deki kayanın üzerinde önünde duracağım. Kayaya vuracaksın ve halk içsin diye oradan su çıkacak.” Moşe İsrael'in ihtiyarlarının önünde böyle yaptı."],["7","İsrael çocukları çekiştiğinden ve “Yahve aramızda mı, değil mi?” diyerek Yahve'yi sınadıkları için bu yere Massa ve Meriva adını verdi."],["8","Sonra Amalek gelip Refidim'de İsrael'le savaştı."],["9","Moşe Yeşu'ya, “Bizim için adamlar seç ve Amalek'le savaşmaya çık” dedi. “Yarın elimde Tanrı'nın değneği ile tepenin zirvesinde duracağım.”"],["10","Yeşu Moşe'nin kendisine söylediği gibi yaptı ve Amalek'le savaştı. Moşe, Aron ve Hur tepenin zirvesine çıktılar."],["11","Moşe elini kaldırdığında İsrael galip geliyordu, elini indirdiğinde Amalek galip geliyordu."],["12","Ama Moşe'nin elleri ağırlaştı, bir taş alıp altına koydular, o da üzerine oturdu. Aron ve Hur, biri bir tarafta, diğeri öbür tarafta onun ellerini kaldırdılar. Gün batımına kadar elleri sabit kaldı."],["13","Yeşu, Amalek'le halkını kılıcın ağzıyla yendi."],["14","Yahve Moşe'ye, “Bunu anma olarak kitaba yaz ve Yeşu'nun kulağına tekrarla” dedi, “Öyle ki, Amalek'in anısını gökyüzünün altından tamamen sileyim.”"],["15","Moşe bir sunak yaptı ve adını “Yahve Sancağımızdır” koydu."],["16","O şöyle dedi: “Yah, 'Yahve Amalek'le kuşaktan kuşağa savaş içinde olacaktır' diye ant içti.”"]],18:[["1","Moşe'nin kayınpederi Midyanlı kâhin Yetro, Tanrı'nın Moşe ve halkı İsrael için yaptığı her şeyi, Yahve'nin İsrael'i Mısır'dan nasıl çıkardığını duydu."],["2","Moşe'nin kayınpederi Yetro, Moşe'nin geri göndermiş olduğu karısı Sippora'yı,"],["3","ve iki oğlunu aldı. Oğullarından birinin adı Gerşom'du, çünkü Moşe, “Yabancı bir ülkede garip olarak yaşadım” dedi."],["4","Diğerinin adı Eliezer'di, çünkü şöyle dedi: “Babamın Tanrısı benim yardımcımdı ve beni Firavun'un kılıcından kurtardı.”"],["5","Moşe'nin kayınpederi Yetro, Moşe'nin oğulları ve karısıyla birlikte Moşe'nin konakladığı çöle, Tanrı Dağı'na geldi."],["6","Moşe'ye, “Ben, kayınpederin Yetro, karın ve iki oğluyla birlikte sana geldim” dedi."],["7","Moşe kayınpederini karşılamaya çıktı, eğilip onu öptü. Birbirlerine hal hatır sorup çadıra girdiler."],["8","Moşe kayınpederine, Yahve'nin İsrael uğruna Firavun'a ve Mısırlılar'a yaptıklarını, yolda başlarına gelen tüm zorlukları ve Yahve'nin onları nasıl kurtardığını anlattı."],["9","Yetro, Yahve'nin İsrael'e yaptığı bütün iyiliklere, onları Mısırlılar'ın elinden kurtardığına sevindi."],["10","Yetro şöyle dedi: “Seni Mısırlılar'ın ve Firavun'un elinden kurtaran Yahve'ye övgüler olsun. Halkı Mısırlılar'ın elinden kurtaran O'dur."],["11","Onların insanlara kibirli davranmalarından artık biliyorum ki, Yahve bütün ilâhlardan daha büyüktür.”"],["12","Moşe'nin kayınpederi Yetro, Tanrı'ya yakmalık sunu ve kurbanlar sundu. Aron, İsrael'in tüm ihtiyarlarıyla birlikte Moşe'nin kayınpederiyle birlikte Tanrı'nın önünde ekmek yemeye geldi."],["13","Ertesi gün Moşe halkı yargılamak için oturdu ve halk sabahtan akşama kadar Moşe'nin çevresinde durdu."],["14","Moşe'nin kayınpederi onun halka yaptıklarını görünce şöyle dedi: “Halk için yaptığınız bu şey nedir? Neden tek başına oturuyorsun ve bütün insanlar sabahtan akşama kadar senin etrafında duruyor?”"],["15","Moşe kayınpederine şöyle dedi: “Çünkü halk Tanrı'ya sormak için bana geliyor."],["16","Bir mesele olduğunda bana gelirler, ben de adamla komşusu arasında hükmederim ve onlara Tanrı'nın hükümlerini ve yasalarını bildiririm.”"],["17","Moşe'nin kayınpederi ona şöyle dedi: “Yaptığın şey iyi değil."],["18","Hem sen, hem de seninle birlikte olan bu halk kesin olarak usanacaksınız. Çünkü bu şey senin için çok ağır. Bunu tek başına kendin yapamazsın."],["19","Şimdi sözümü dinle. Sana öğüt vereyim ve Tanrı seninle olsun. Sen halk için Tanrı'nın önünde ol ve konuları Tanrı'ya getir."],["20","Onlara hükümleri ve yasaları öğretirsin, yürümeleri gereken yolu ve yapmaları gereken işi onlara gösterirsin."],["21","Ayrıca bütün halk arasından Tanrı'dan korkan yetenekli adamlar, haksız kazançtan nefret eden dürüst adamlar çıkar. Onları, binlerin başı, yüzlerin başı, ellilerin başı ve onların başı olarak onların üzerine koy."],["22","Halkı her zaman onlar yargılasınlar. Öyle olacak ki, her büyük meseleyi sana getirecekler, ama her küçük meseleyi kendileri yargılayacaklar. Böylece işin kolaylaşacak ve yükü seninle paylaşacaklar."],["23","Eğer bunu yaparsan, Tanrı da sana öyle buyurursa, o zaman dayanabilirsin ve bütün bu halk da esenlik içinde yerine gider.”"],["24","Böylece Moşe kayınpederinin sözünü dinledi ve söylediklerinin hepsini yaptı."],["25","Moşe tüm İsrael'den yetenekli adamlar seçti ve onları halkın üzerine, binlere, yüzlere, ellilere ve onlara baş yaptı."],["26","Halkı her zaman yargıladılar. Zor davaları Moşe'ye getirdiler, ama her küçük meseleyi kendileri yargıladılar."],["27","Moşe kayınpederinin gitmesine izin verdi ve o da kendi ülkesine doğru yola çıktı."]],19:[["1","İsrael'in çocukları Mısır diyarından çıktıktan sonraki üçüncü ayda, aynı gün Sina Çölü'ne geldiler."],["2","Refidim'den ayrılıp Sina Çölü'ne vardıklarında çölde konakladılar. İsrael orada dağın önünde konakladı."],["3","Moşe Tanrı'nın yanına çıktı. Yahve dağdan onu çağırıp şöyle dedi: “Yakov'un evine ve İsrael'in çocuklarına şunu söyleyeceksin:"],["4","'Mısırlılar'a ne yaptığımı, sizi nasıl kartal kanatları üzerinde taşıdığımı ve sizi kendime getirdiğimi gördünüz."],["5","Şimdi, eğer gerçekten sözümü dinlerseniz ve antlaşmamı tutarsanız, o zaman bütün halklar arasında benim kendi mülküm olursunuz; çünkü bütün dünya benimdir."],["6","Sizler bana kâhinler krallığı ve kutsal bir ulus olacaksınız.' İsrael'in çocuklarına söyleyeceğin sözler bunlardır.”"],["7","Moşe gelip halkın ihtiyarlarını çağırdı ve Yahve'nin kendisine buyurduğu tüm bu sözleri onların önüne koydu."],["8","Bütün halk hep birlikte şöyle yanıt verdi: “Yahve'nin söylediği her şeyi yapacağız.” Moşe halkın sözlerini Yahve'ye bildirdi."],["9","Yahve Moşe'ye şöyle dedi: “Seninle konuştuğumu halk duysun, hem de sana daima inansınlar diye, sana koyu bir bulut içinde geleceğim.” Moşe halkın sözlerini Yahve'ye bildirdi."],["10","Yahve Moşe'ye şöyle dedi: “Halka git, onları bugün ve yarın kutsa, giysilerini yıkasınlar,"],["11","ve üçüncü günde hazır olsunlar, çünkü üçüncü gün Yahve bütün halkın gözü önünde Sina Dağı'na inecek."],["12","'Dikkat edin, dağa çıkmayın, sınırına dokunmayın diyerek çevredeki insanlara sınır koyacaksın. Kim dağa dokunursa kesin olarak öldürülecektir."],["13","Ona kimse dokunmayacak; mutlaka taşlanacak ya da vurulacak; ister hayvan olsun ister insan, yaşamayacaktır.' Boru uzun süre çalınca dağa çıkacaklar.”"],["14","Moşe dağdan halkın yanına indi ve halkı kutsadı ve elbiselerini yıkadılar."],["15","Halka, “Üçüncü güne hazır olun” dedi. “Bir kadınla cinsel ilişkiye girmeyin.”"],["16","Üçüncü gün sabah olduğunda gök gürlemeleri, şimşekler, dağın üzerinde koyu bir bulut ve çok güçlü boru sesi oldu ve ordugâhta bulunan herkes titredi."],["17","Moşe Tanrı'nın huzuruna çıkmak için halkı ordugâhtan çıkardı. Dağın eteğinde durdular."],["18","Yahve ateş içinde onun üzerine indiği için Sina Dağı'nın tamamı tütüyordu. Dumanı ocak dumanı gibi yükseldi ve bütün dağ şiddetle sarsıldı."],["19","Borunun sesi git gide yükselince Moşe konuştu ve Tanrı ona sesle yanıt verdi."],["20","Yahve Sina Dağı'nın zirvesine indi. Yahve Moşe'yi dağın zirvesine çağırdı ve Moşe yukarı çıktı."],["21","Yahve Moşe'ye şöyle dedi: “Aşağı in ve halkı uyar, yoksa görmek için Yahve'ye doğru sınırı aşarlar, onlardan çoğu yok olurlar."],["22","Yahve'ye yaklaşan kâhinler de kendilerini kutsasınlar, yoksa Yahve onlara saldırır.”"],["23","Moşe Yahve'ye şöyle dedi, “Halk Sina Dağı'na çıkamaz, çünkü sen bizi uyardın: 'Dağın çevresine sınırlar koy ve onu kutsa' demiştin.”"],["24","Yahve ona, “Aşağı in!” dedi. “Aron'u da yanında getireceksin, ama kâhinler ve halk Yahve'ye doğru çıkmasınlar, yoksa onlara saldırır.”"],["25","Bunun üzerine Moşe halkın yanına indi ve onlara anlattı."]],20:[["1","Tanrı bütün bu sözleri söyleyip şöyle dedi:"],["2","“Seni Mısır diyarından, esaret evinden çıkaran Tanrın Yahve benim.”"],["3","“Önümde başka ilâhların olmayacak.”"],["4","“Kendin için bir put, yukarıda göklerde olanın, ya da aşağıda yerde olanın ya da yerin altında sularda olanın herhangi bir suretini yapmayacaksın."],["5","Onlara eğilmeyeceksin; çünkü ben, Tanrın Yahve, benden nefret edenlerin babalarının suçunu çocuklarına, üçüncü ve dördüncü kuşaklarına çektiren,"],["6","ve beni seven ve buyruklarımı tutanların binlercesine sevgi dolu iyilik gösteren, kıskanç bir Tanrı'yım.”"],["7","“Tanrın Yahve'nin adını hor kullanmayacaksın; çünkü Yahve, adını hor kullananı suçsuz tutmayacaktır.”"],["8","“Şabat Günü'nü kutsal tutmak için onu hatırla."],["9","Altı gün çalışacak ve tüm işini yapacaksın."],["10","Ama yedinci gün Tanrın Yahve için Şabat'dır. Sen, oğlun, kızın, erkek kölen, kadın kölen, hayvanların ve kapılarında olan yabancı onda hiçbir iş yapmayacak."],["11","Çünkü Yahve göğü, yeri, denizi ve içlerindeki her şeyi altı günde yarattı ve yedinci gün dinlendi; bu nedenle Yahve Şabat Günü'nü kutsadı ve onu kutsal kıldı.”"],["12","“Babana ve annene saygı göster ki, Tanrın Yahve'nin sana vereceği toprakta günlerin uzun olsun."],["13","“Öldürmeyeceksin.”"],["14","“Zina etmeyeceksin.”"],["15","“Çalmayacaksın.”"],["16","“Komşuna karşı yalan yere tanıklık etmeyeceksin.”"],["17","“Komşunun evine göz dikmeyeceksin. Komşunun karısına, erkek hizmetçisine, kadın hizmetçisine, öküzüne, eşeğine ve komşunun hiçbir şeyine tamah etmeyeceksin.”"],["18","Bütün halk gök gürlemelerini, şimşekleri, boru sesini ve dağdan yükselen dumanı fark etti. İnsanlar bunu görünce titrediler ve uzakta durdular."],["19","Moşe'ye, “Bizimle sen konuş, biz de dinleyelim” dediler. “Ama Tanrı bizimle konuşmasın, yoksa ölürüz.”"],["20","Moşe halka, “Korkmayın, çünkü Tanrı sizi sınamak ve günah işlemeyesiniz, O'nun korkusu önünüzde olsun diye geldi” dedi."],["21","Halk uzakta durdu ve Moşe, Tanrı'nın bulunduğu koyu karanlığa yaklaştı."],["22","Yahve Moşe'ye şöyle dedi: “İsrael'in çocuklarına bunu söyleyeceksin: 'Sizinle gökten konuştuğumu kendiniz gördünüz."],["23","Benim yanımsıra kendinize gümüşten ya da altından ilâhlar kesinlikle yapmayacaksınız."],["24","Benim için topraktan bir sunak yapacaksın ve yakmalık sunularını, esenlik sunularını, koyunlarını ve sığırlarını onun üzerinde kurban edeceksin. Adımı hatırlattığım her yerde sana geleceğim ve seni kutsayacağım."],["25","Eğer bana taştan bir sunak yaparsan, onu yontma taşlardan yapmayacaksın; çünkü eğer aletini onun üzerine kaldırırsan, onu kirletmiş olursun."],["26","Çıplaklığınız ortaya çıkmasın diye, sunağıma basamakla çıkmayacaksınız.'”"]],21:[["1","“Şimdi onların önüne koyacağın hükümler şunlardır:”"],["2","“Eğer İbrani bir hizmetçi satın alırsan, altı yıl hizmet edecek ve yedincisinde hiçbir şey ödemeden özgür olarak çıkacak."],["3","Eğer yalnız geldiyse, tek başına çıkacaktır. Evli ise karısı da onunla birlikte çıkacaktır."],["4","Eğer efendisi ona bir eş verir ve o kadın ona oğulları ya da kızları doğurursa, karısı ve çocukları efendisinin olacak ve kendisi tek başına çıkacaktır."],["5","Ama hizmetçi açıkça, 'Efendimi, karımı ve çocuklarımı seviyorum' derse;”"],["6","o zaman efendisi onu Tanrı'ya getirecek. Onu kapıya ya da kapı sövesine getirecek ve efendisi bizle onun kulağını delecek. O da ona daima hizmet edecektir."],["7","“Eğer bir adam kızını hizmetçi olarak satarsa, kız erkek hizmetçiler gibi dışarı çıkmayacaktır."],["8","Eğer kendisiyle evlenmiş olan kız, efendisini memnun etmezse, efendisi onun geri satın alınmasına izin verecektir. Ona hileyle davrandığı için onu yabancı bir halka satmaya hakkı olmayacaktır."],["9","Eğer onu kendi oğluyla evlendirirse, ona kızı gibi davranacaktır."],["10","Eğer kendine başka bir kadın alırsa, öncekinin yiyeceğini, giyeceğini ve evlilik haklarını kısmayacaktır."],["11","Eğer bu üç şeyi onun için yapmazsa, kadın hiçbir para ödemeden özgür gidebilir.”"],["12","“Bir adamı vuran, vurduğu kişi de ölürse, kesinlikle öldürülecektir."],["13","Ama bu kasıtsızsa, Tanrı bunun olmasına izin vermişse, o zaman sana onun kaçacağı bir yer tayin edeceğim."],["14","Eğer bir kişi kendisini öldürmek için komşusuna düzen kurar ve haddini bilmez bir şekilde komşusunun üstüne gelirse, onu ölsün diye sunağımdan alacaksınız.”"],["15","“Babasına ya da annesine saldıran kesinlikle öldürülecektir.”"],["16","“Birini kaçırıp satan ya da elinde bulunduran kişi kesinlikle öldürülecektir.”"],["17","“Babasına ya da annesine lanet eden kesinlikle öldürülecektir.”"],["18","“Eğer insanlar kavga eder ve biri diğerine taşla ya da yumrukla vurursa, o da ölmeyip yatağa mahkûm olursa;"],["19","eğer tekrar ayağa kalkıp değneğiyle dolaşırsa, ona vuran aklanacak, yalnızca kaybettiği zamanın bedelini kendisi ödeyecek ve tamamen iyileşene dek iyileşmesini karşılayacaktır.”"],["20","“Eğer bir adam hizmetçisine ya da kadın hizmetçisine değnekle vurursa ve o kişi onun eli altında ölürse, o adam kesinlikle cezalandırılacaktır."],["21","Bununla birlikte, eğer hizmetçisi bir ya da iki gün sonra kalkarsa cezalandırılmaz; çünkü hizmetçi onun mülküdür.”"],["22","“Eğer insanlar kavga edip gebe bir kadını incitir, kadın da düşük yaparsa ve hiçbir zarar gelmese de, mutlaka kadının kocasının talep edeceği ve hakimlerin izin vereceği ölçüde para cezasına çarptırılacaktır."],["23","Ama bundan bir zarar gelirse, cana karşılık can,"],["24","göze karşılık göz, dişe karşılık diş, ele karşılık el, ayağa karşılık ayak,"],["25","yanmaya karşılık yanma, yaraya karşılık yara, bereye karşılık bere alacaksın.”"],["26","“Eğer bir adam hizmetçisinin ya da kadın hizmetçisinin gözüne vurup onu sakatlarsa, gözü uğruna onu özgür bırakacaktır."],["27","Eğer erkek hizmetçisinin ya da kadın hizmetçisinin dişine vurursa, dişi uğruna hizmetçiyi özgür bırakacaktır.”"],["28","“Eğer bir boğa bir erkeği ya da kadını süsüp öldürürse, boğa kesinlikle taşlanacak ve eti yenmeyecektir; ancak boğanın sahibi sorumlu tutulmayacaktır."],["29","Ancak boğanın geçmişte süsme alışkanlığı varsa ve bu durum sahibine bildirilmişse ve o da onu içeride tutmamışsa ve bir erkeği ya da kadını öldürmüşse, boğa taşlanacak, sahibi de öldürülecektir."],["30","Eğer kendisi üzerine bir fidye konulursa, o zaman hayatının fidyesi olarak üzerine konulan ne ise ödeyecektir."],["31","İster oğlunu, ister kızını süsmüş olsun, ona bu hükme göre yapılacaktır."],["32","Eğer boğa bir erkek ya da kadın hizmetçiyi süserse, efendilerine otuz şekel gümüş verilecek ve öküz taşlanacaktır.”"],["33","“Eğer bir kişi bir çukur açar, ya da bir kişi bir çukur kazar ve onu örtmezse ve içine bir boğa ya da eşek düşerse,"],["34","çukurun sahibi karşılığını ödeyecektir. Parayı onların sahibine verecek ve ölü hayvan kendisinin olacaktır.”"],["35","“Eğer birinin boğası başka birinin boğasını yaralar o da ölürse, o zaman canlı boğayı satıp bedelini bölüşecekler; ölü hayvanı da böleceklerdir."],["36","Ya da boğanın geçmişte süsme alışkanlığı olduğu biliniyorsa ve sahibi onu içeride tutmamışsa, kesinlikle boğa karşılığında boğa ödeyecek ve ölü hayvan kendisinin olacaktır.”"]],22:[["1","“Eğer biri bir öküz ya da koyun çalar ve onu öldürür ya da satarsa, bir öküz için beş öküz, bir koyun için dört koyun ödeyecektir."],["2","Eğer hırsız içeri girerken yakalanır ve vurularak ölürse, onun için kan dökme suçu yoktur."],["3","Eğer güneş onun üzerine doğmuşsa, kan dökmeden suçludur. Zararı karşılayacaktır. Hiçbir şeyi yoksa hırsızlıktan dolayı satılacaktır."],["4","Çalınan mal, ister öküz, ister eşek, ister koyun olsun, elinde canlı olarak bulunursa, iki katını ödeyecek.”"],["5","“Eğer biri hayvanını salıverip bir tarladan ya da bağdan yedirirse ve hayvan başka bir adamın tarlasında otluyorsa, karşılığını kendi tarlasının ya da bağının en iyisiyle ödeyecektir.”"],["6","“Eğer yangın çıkar dikenlere sıçrar ve ekinler, ekin demetleri ya da tarla yanarsa; ateşi tutuşturan, kesinlikle karşılığını ödeyecektir.”"],["7","“Biri komşusuna saklaması için para ya da eşya verir ve bunlar adamın evinden çalınırsa, eğer hırsız bulunursa iki katını ödeyecektir."],["8","Hırsız bulunamazsa, evin sahibi, komşusunun eşyasına el atıp atmadığını öğrenmek için Tanrı'ya yaklaşacaktır."],["9","Her suç meselesi hakkında, ister öküz, eşek, koyun, giysi ya da herhangi bir kayıp eşyayla ilgili olsun, 'Bu benimdir' diyen her iki tarafın davası Tanrı'ya getirilecektir. Tanrı'nın suçlu çıkardığı kişi komşusuna iki kat ödeyecektir.”"],["10","“Eğer biri komşusuna bakması için bir eşek, bir öküz, bir koyun ya da herhangi bir hayvan teslim ederse ve bu hayvan ölürse, yaralanırsa ya da sürülüp götürülürse ve onu kimse görmezse;"],["11","komşusunun malına el sürmemiştir diye, Yahve'nin andı ikisi arasında olacaktır; sahibi bunu kabul edecek ve karşılık ödemeyecektir."],["12","Ama eğer ondan çalınmışsa, çalan kişi, sahibine karşılığını ödeyecektir.”"],["13","Parçalanmışsa kanıt olarak getirsin. Parçalanmış olanı ödemeyecektir."],["14","“Eğer biri komşusundan bir şey ödünç alırsa ve o şey sahibi yanında olmadan yaralanırsa ya da ölürse, kesinlikle borcunu ödeyecektir."],["15","Eğer sahibi onun yanındaysa, ödemeyecektir. Eğer kiralık bir şeyse, kirasına sayılacaktır.”"],["16","“Bir adam nişanlı olmayan el değmemiş bir kızı ayartıp onunla yatarsa, onun karısı olması için kesinlikle bir çeyiz ödeyecektir."],["17","Eğer babası onu kendisine vermeyi tümüyle reddederse, el değmemiş kızların çeyizine göre para ödeyecektir.”"],["18","“Büyücünün yaşamasına izin vermeyeceksin.”"],["19","“Kim bir hayvanla cinsel ilişkiye girerse kesinlikle öldürülecektir.”"],["20","“Yalnız Yahve'nin dışında başka bir ilâha kurban sunan kişi tümüyle yok edilecek.”"],["21","“Bir yabancıya haksızlık etmeyeceksin ve onu ezmeyeceksin; çünkü siz Mısır diyarında yabancıydınız.”"],["22","“Hiçbir dul kadını ya da yetimi istismar etmeyeceksiniz."],["23","Onları bir şekilde istismar eder ve bana feryat ederlerse, feryatlarını mutlaka duyacağım;"],["24","ve öfkem alevlenecek ve sizi kılıçla öldüreceğim; ve karılarınız dul, çocuklarınız yetim kalacaklar.”"],["25","“Eğer halkımdan yanında olan yoksul birine borç verirsen, ona tefeci gibi olmayacaksın. Ondan faiz almayacaksın."],["26","Eğer komşunun giysisini rehin olarak alırsan, onu güneş batmadan önce ona geri vereceksin."],["27","Çünkü bu onun tek örtüsüdür, bu onun derisinin giysisidir. Neyle yatsın? Böyle olacak, o bana feryat ettiğinde onu duyacağım, çünkü ben lütufkârım.”"],["28","“Tanrı'ya sövmeyeceksin, halkının hükümdarına lanet etmeyeceksin.”"],["29","“Hasatınızdan ve masaranızdan çıkanı sunmakta gecikmeyeceksiniz.” “Oğullarının ilk doğanı bana vereceksin.”"],["30","Sığırlarınız ve koyunlarınız için de aynısını yapacaksınız. Yedi gün annesiyle birlikte kalacak, sonra sekizinci gün onu bana vereceksiniz.”"],["31","“Siz benim için kutsal insanlar olacaksınız; bu nedenle kırda hayvanların parçaladığı etleri yemeyeceksiniz. Onu köpeklere atacaksınız.”"]],23:[["1","“Yalan haber yaymayacaksın. Kötü niyetli tanık olmak için kötüye el vermeyeceksin.”"],["2","“Kötülük yapmak için kalabalığın peşinden gitmeyeceksin. Adaleti saptırmak için mahkemede kalabalığın yanında tanıklık yapmayacaksın."],["3","Davasında yoksulu kayırmayacaksın.”"],["4","“Eğer düşmanının öküzünü ya da eşeğini yoldan sapmış halde bulursan, onu mutlaka kendisine geri getireceksin."],["5","Eğer senden nefret edenin eşeğinin yükü altında çökmüş görürsen, onu yalnız bırakmayacaksın. Bu konuda ona mutlaka yardım edeceksin.”"],["6","“Yoksul halkınızın davalarında adaleti saptırmayacaksın.”"],["7","“Yalan suçlamadan uzak dur, suçsuzu ve doğruyu öldürme; çünkü ben kötüyü aklamam.”"],["8","“Rüşvet almayacaksın; çünkü rüşvet, görenleri kör eder ve doğruların sözlerini saptırır.”"],["9","“Yabancıyı ezmeyeceksin; çünkü siz Mısır diyarında yabancı olduğunuz için, yabancının yüreğini bilirsiniz.”"],["10","“Toprağını altı yıl ekeceksin ve ürününü toplayacaksın."],["11","Ama yedinci yıl onu, halkınızın yoksulları yiyebilsin diye dinlenmeye ve nadasa bırakacaksın; onların bıraktıklarını da kır hayvanı yiyecek. Bağın ve zeytinliğin için de aynı şekilde yapacaksın.”"],["12","“Altı gün işini yapacaksın, yedinci gün dinleneceksin ki, öküzün, eşeğin, hizmetçinin oğlu ve yabancı ferahlasın.”"],["13","“Size söylediğim her şeyi yapmaya dikkat edin; ve başka ilâhların adını anmayın ve onlar ağzında bile duyulmasın.”"],["14","“Yılda üç kez bana bayram edeceksiniz."],["15","Mayasız Ekmek Bayramı'nı tutacaksınız. Size buyurduğum gibi, Aviv ayının belirlenen vaktinde (çünkü Mısır'dan o ayda çıktınız) yedi gün mayasız ekmek yiyeceksiniz ve kimse önüme boş çıkmayacak."],["16","Tarlaya ekmiş olduğunuz emeğinizin ilk ürünü olan Hasat Bayramı'nı; yıl sonunda, tarladan emeklerinizi topladığınız zaman Toplama Bayramı'nı tutacaksınız."],["17","Bütün erkekleriniz yılda üç kez Efendi Yahve'nin önünde görünecek.”"],["18","“Kurbanımın kanını mayalı ekmekle sunmayacaksın. Bayramımın yağı bütün gece sabaha kadar kalmayacak."],["19","Toprağınızın seçme ilk ürünlerini Tanrınız Yahve'nin Tapınağı'na getireceksiniz.” “Oğlağı anasının sütünde kaynatmayacaksınız.”"],["20","“İşte, size yolda bakması ve hazırladığım yere getirmesi için önünüzden bir Melek gönderiyorum."],["21","O'na dikkat edin ve sözünü dinleyin. O'nu kışkırtmayın, çünkü O itaatsizliğinizi bağışlamayacaktır; çünkü benim adım Onda'dır."],["22","Ama gerçekten onun sözünü dinler ve söylediklerimin hepsini yaparsanız, o zaman düşmanlarınıza düşman, hasımlarınıza hasım olacağım."],["23","Çünkü Melek'im önünüzden gidecek ve sizi Amorlular'ın, Hititler'in, Perizliler'in, Kenanlılar'ın, Hivliler'in ve Yevuslular'ın yanına getirecek; ben de onları kesip koparacağım."],["24","Onların ilâhlarına eğilmeyecek, onlara hizmet etmeyecek, onların uygulamalarını izlemeyeceksiniz; tersine onları tamamen devirecek ve dikili taşlarını yıkacaksınız."],["25","Tanrınız Yahve'ye hizmet edeceksiniz, O da ekmeğinizi ve suyunuzu bereketleyecek, ben de aranızdan hastalıkları kaldıracağım."],["26","Ülkenizde kimse düşük yapmayacak, kısır bulunmayacak. Günlerinizin sayısını tamamına erdireceğim."],["27","Önünüzden dehşetimi salacağım, karşılaşacağınız bütün halkları şaşkına çevireceğim, bütün düşmanlarınızın size sırtını çevirteceğim."],["28","Hivliler'i, Kenanlılar'ı, Hititliler'i önünüz sıra kovacak, eşek arısını önünüzden göndereceğim."],["29","Ülke ıssız kalmasın, kır hayvanları size karşı çoğalmasın diye, onları bir yıl içinde önünüzden kovmayacağım."],["30","Siz çoğalıncaya ve ülkeyi miras alana dek onları azar azar önünüzden kovacağım."],["31","Sınırınızı Kızıldeniz'den Filist denizine kadar, çölden o Nehre kadar koyacağım; çünkü ülkede yaşayanları elinize teslim edeceğim ve siz onları önünüzden kovacaksınız."],["32","Onlarla ve ilâhlarıyla antlaşma yapmayacaksınız."],["33","Bana karşı günah işlememeniz için ülkenizde oturmayacaklar. Çünkü onların ilâhlarına hizmet ederseniz, bu kesin olarak sizin için bir tuzak olacaktır.”"]],24:[["1","Ve Moşe'ye şöyle dedi: “Sen, Aron, Nadav, Avihu ve İsrael ihtiyarlarından yetmiş kişi Yahve'nin yanına çıkın; ve uzaktan tapının."],["2","Yalnız Moşe Yahve'ye yaklaşacak, ama onlar yaklaşmayacak. Halk onunla birlikte çıkmayacak.”"],["3","Moşe gelip Yahve'nin bütün sözlerini ve bütün hükümlerini halka anlattı; bütün halk da bir sesle yanıt verdi ve: “Yahve'nin söylediği bütün sözleri yapacağız.” dedi."],["4","Moşe Yahve'nin tüm sözlerini yazdı, sonra sabah erkenden kalktı ve dağın eteğinde İsrael'in on iki oymağı için on iki sütunlu bir sunak kurdu."],["5","İsrael'in çocuklarından gençler gönderdi, Yahve'ye yakmalık sunular sundular, esenlik kurbanı olarak boğalar kestiler."],["6","Moşe kanın yarısını leğenlere koydu, yarısını da sunağın üzerine serpti."],["7","Antlaşma kitabını alıp halkın önünde okudu ve onlar, “Yahve'nin bütün söylediklerini yapacağız ve itaat edeceğiz” dediler."],["8","Moşe kanı alıp halkın üzerine serpti ve şöyle dedi: “İşte, bu, tüm bu sözlerle ilgili olarak Yahve'nin sizinle yaptığı antlaşmanın kanıdır.”"],["9","Bunun üzerine Moşe, Aron, Nadav, Avihu ve İsrael'in ihtiyarlarından yetmiş kişi yukarı çıktılar."],["10","İsrael'in Tanrısı'nı gördüler. Ayaklarının altında safir taşını andıran bir döşeme vardı; sanki gökyüzünün berraklığı gibiydi."],["11","İsrael'in çocuklarının soylularına el sürmedi. Tanrı'yı gördüler, yediler, içtiler."],["12","Yahve Moşe'ye şöyle dedi: “Dağa, yanıma çık ve burada kal. Onlara öğretebilmen için yazdığım yasa ve buyruklarının bulunduğu taş levhalarını sana vereceğim.”"],["13","Moşe ile hizmetkârı Yeşu kalktılar ve Moşe Tanrı Dağı'na çıktı."],["14","İhtiyarlara şöyle dedi: “Biz tekrar yanınıza gelinceye dek bizi burada bekleyin. İşte Aron ve Hur sizinle birlikteler. Anlaşmazlığa düşen herkes onlara gidebilir.”"],["15","Moşe dağa çıktı ve bulut dağı örttü."],["16","Yahve'nin görkemi Sina Dağı'nın üzerinde durdu ve bulut onu altı gün boyunca örttü. Yedinci gün bulutun içinden Moşe'yi çağırdı."],["17","Yahve'nin görkeminin görünüşü, İsrael'in çocuklarının gözünde dağın zirvesinde yiyip bitiren ateş gibiydi."],["18","Moşe bulutun içine girip dağa çıktı; Moşe kırk gün kırk gece dağda kaldı."]],25:[["1","Yahve Moşe'ye şöyle konuştu:"],["2","“İsrael'in çocuklarına söyle, bana sunu getirsinler. Yüreği istekli olan herkesten sunumu alacaksın."],["3","Onlardan alacağın sunular şunlardır: Altın, gümüş, tunç,"],["4","mavi, mor, kırmızı, ince keten, keçi kılı,"],["5","kırmızı boyalı koç derileri, deniz ayısı derileri, akasya ağacı,"],["6","kandil için yağ, mesh yağı ve hoş kokulu buhur için baharatlar,"],["7","oniks taşları, efod ve göğüslük için kakılacak taşlar."],["8","Aralarında oturmam için bana kutsal bir yer yapsınlar."],["9","Sana gösterdiğim her şeye, konutun örneğine ve içindeki tüm takımların örneğine göre, öyle yapacaksın.”"],["10","“Akasya ağacından bir sandık yapacaklar. Uzunluğu iki buçuk arşın, eni bir buçuk arşın ve yüksekliği bir buçuk arşın olacak."],["11","Onu saf altınla kaplayacaksın. İçini ve dışını kaplayacaksın, çevresine de altın pervaz yapacaksın."],["12","Onun için dört altın halka dökeceksin ve onları dört ayağına takacaksın. Bir tarafında iki halka, diğer tarafında iki halka bulunacaktır."],["13","Akasya ağacından sırıklar yapacaksın ve onları altınla kaplayacaksın."],["14","Sandığı taşımak için sırıkları sandığın yanlarındaki halkalara takacaksın."],["15","Sırıklar sandığın halkalarında kalacak. Ondan ayrılmayacaklar."],["16","Sana vereceğim antlaşmayı sandığın içine koyacaksın."],["17","Saf altından bir merhamet örtüsü yapacaksın. Uzunluğu iki buçuk arşın, genişliği bir buçuk arşın olacak."],["18","Dövme altından iki keruv yapacaksın. Bunları merhamet örtüsünün iki ucuna yapacaksın."],["19","Bir uçta bir keruv, diğer uçta öbür keruvu yap. Keruvların iki ucunu merhamet örtüsüyle birlikte tek parça yapacaksın."],["20","Keruvlar kanatlarını yukarıya doğru açacak, yüzleri birbirine bakacak şekilde merhamet örtüsünü kanatlarıyla örtecekler. Keruvların yüzleri merhamet örtüsüne doğru olacak."],["21","Merhamet örtüsünü sandığın üstüne koyacaksın ve sana vereceğim antlaşmayı sandığın içine koyacaksın."],["22","Orada seninle buluşacağım ve İsrael'in çocukları için sana buyuracağım her şeyi, antlaşma sandığı üzerindeki iki keruvun arasından, merhamet örtüsünün üzerinden sana söyleyeceğim.”"],["23","“Akasya ağacından bir masa yapacaksın. Uzunluğu iki arşın, eni bir arşın ve yüksekliği bir buçuk arşın olacak."],["24","Onu saf altınla kaplayacaksın ve çevresine altın pervaz yapacaksın."],["25","Çevresine bir karış genişliğinde bir kenar yapacaksın. Kenarın çevresine altın pervaz yapacaksın."],["26","Onun için dört altın halka yapacaksın ve halkaları dört ayağının dört köşesine yerleştireceksin."],["27","Masayı taşıyacak sırıkların yeri için halkalar kenara yakın olacak."],["28","Sırıkları akasya ağacından yapacaksın, onları altınla kaplayacaksın ve masa onlarla taşınacak."],["29","Onun tabaklarını, kaşıklarını, kepçelerini, sunuları dökeceğiniz taslarını siz yapacaksınız. Onları saf altından yapacaksın."],["30","Huzur ekmeğini her zaman önüme koyacaksın.”"],["31","“Saf altından bir şamdan yapacaksın. Şamdanın ayağı ve gövdesi dövmeci işi olacak. Tabanı, gövdesi, çanakları, tomurcukları ve çiçekleri ondan tek parça olacak."],["32","Yanlarından altı kol çıkacak: şamdanın bir yanından üç kol, diğer yanından da üç kol çıkacak;"],["33","bir kolda badem çiçeğine benzeyen üç tas, bir tomurcuk ve bir çiçek; diğer kolda da badem çiçeğine benzeyen üç tas, bir tomurcuk ve bir çiçek olacak, şamdandan çıkan altı kol için böyle olacaktır;"],["34","şamdanda badem çiçeğine benzer dört tas, onun tomurcukları ve çiçekleri olacaktır;"],["35","ondan çıkan altı kol için, iki kol altında kendinden bir tomurcuk, iki kol altında kendinden bir tomurcuk ve iki kol altında kendinden bir tomurcuk olacaktır."],["36","Tomurcukları ve kolları onunla tek parça olacak; hepsi saf altından dövmeci işi olacaktır."],["37","Onun kandillerini yedi tane yapacaksın; onlar da önündeki boşluğa ışık versin diye kandillerini yakacaklar."],["38","Makasları ve tablaları saf altından olacak."],["39","Bütün bu takımlarla birlikte bir talant saf altından yapılacak."],["40","Bak, bunları dağda sana gösterilen örneklerine göre yap.”"]],26:[["1","“Dahası konutu ince ketenden, mavi, erguvani ve kırmızı, keruvlarla on perdeyle yapacaksın. Bunları usta bir işçinin işiyle yapacaksın.”"],["2","Her perdenin uzunluğu yirmi sekiz arşın, her perdenin eni dört arşın olacak; bütün perdelerin bir ölçüsü olacak."],["3","Beş perde birbirine bağlanacak, diğer beş perde de birbirine bağlanacak."],["4","Bağlantı parçasındaki kenardan itibaren bir perdenin kenarına mavi ilmekler yapacaksın; aynısını ikinci bağlantı parçasındaki perdenin en dıştaki kenarına da yapacaksın."],["5","Bir perdede elli ilmek yapacaksın ve ikinci bağlamadaki perdenin kenarında da elli ilmek yapacaksın. İlmekler birbirinin karşısında olacak."],["6","Elli altın kopça yapacaksın ve perdeleri kopçalarla birbirine bağlayacaksın. Konut tek parça olacaktır."],["7","“Konutun üzerini örtmek için keçi kılından perdeler yapacaksın. On bir perde yapacaksın."],["8","Her perdenin uzunluğu otuz arşın, her perdenin eni dört arşın olacak; on bir perdenin bir ölçüsü olacak."],["9","Beş perdeyi ayrı ayrı, altı perdeyi ayrı ayrı birleştireceksin; altıncı perdeyi çadırın ön tarafında ikiye katlayacaksın."],["10","Bağlamadaki en dıştaki perdenin kenarına elli ilmek, ikinci bağlamadaki en dıştaki perdenin kenarına elli ilmek yapacaksın."],["11","Elli tunç kopça yapacaksın, kopçaları ilmeklere geçireceksin ve çadırı birleştireceksin ki, tek parça olsun."],["12","Çadırın perdelerinden artan yarım perde, çadırın arka kısmından sarkacak."],["13","Çadırın perdelerinin uzunluğundan artakalan miktarın bir yanda ve diğer yanda arşın kadarı, çadırı örtmek için bu yanda ve öte yanda, çadırın yanlarından sarkacak."],["14","Çadır için kırmızı boyalı koç derilerinden bir örtü, üstüne de deniz ayısı derilerinden bir örtü yapacaksın.”"],["15","“Konutun çerçevelerini dik duracak şekilde akasya ağacından yapacaksın."],["16","Bir çerçevenin uzunluğu on arşın, her bir çerçevenin eni bir buçuk arşın olacak."],["17","Her kenarda birbirine bağlı iki geçmesi olacak; çadırın bütün çerçevelerini böyle yapacaksın."],["18","Konutun güney tarafı, güney yönü için yirmi çerçeve yapacaksın."],["19","Yirmi çerçevenin altına kırk gümüş taban; iki geçmesi için bir çerçevenin altında iki taban ve iki geçmesi için başka bir çerçevenin altında iki geçme yapacaksın."],["20","Konutun kuzey tarafı, ikinci yanı için yirmi çerçeve,"],["21","ve bir çerçeve altında iki taban, diğer çerçeve altında iki taban olmak üzere bunların kırk gümüş tabanını yapacaksın."],["22","Konutun batıya bakan uzak tarafı için altı çerçeve yapacaksın."],["23","Konutun uzak tarafındaki köşeleri için iki çerçeve yapacaksın."],["24","Aşağıda çift olacaklar ve aynı şekilde tepeden tek halkaya kadar çift olacaklar; ikisi için de böyle olacak; onlar iki köşe için olacak."],["25","Sekiz çerçeve ve bunların gümüş tabanları, bir çerçeve altında iki taban ve diğer çerçevenin altında iki taban olmak üzere, onların on altı tabanları olacak.”"],["26","“Konutun bir tarafındaki çerçeveler için beş, konutun diğer tarafındaki çerçeveler için beş,"],["27","ve konutun doğu uzak tarafındaki çerçeveler için beş olmak üzere akasya ağacından kirişler yapacaksın."],["28","Çerçevelerin ortasındaki orta kiriş bir uçtan bir uca geçecek."],["29","Çerçeveleri altınla kaplayacaksın, ve kirişlerin yeri olarak altın halkalar yapacaksın. Kirişleri altınla kaplayacaksın."],["30","Konutu dağda sana gösterildiği şekle göre kuracaksın.”"],["31","“Lacivert, mor, kırmızı ve ince dokunmuş ince ketenden keruvlarla bir perde yapacaksın. Usta bir işçinin işi olacak."],["32","Onu altınla kaplanmış akasya ağacından dört sütun üzerine asacaksın. Çengelleri dört gümüş taban üzerinde altından olacak."],["33","Perdeyi kopçaların altına asacaksın ve Antlaşma Sandığı'nı perdenin içine, oraya getireceksin. Perde sizin için Kutsal Yeri En Kutsal Yer'den ayıracaktır."],["34","Merhamet Örtüsü'nü Antlaşma Sandığı'nın üzerine, En Kutsal Yer'e koyacaksın."],["35","Masayı perdenin dışına koyacaksın, şamdanı da masanın karşısına, çadırın güney tarafına koyacaksın. Masayı kuzey tarafına koyacaksın.”"],["36","“Çadırın kapısına mavi, mor, kırmızı ve özenle dokunmuş ince ketenden nakışçı işi bir perde yapacaksın."],["37","Perde için akasya ağacından beş direk yapacaksın ve onları altınla kaplayacaksın. Çengelleri altından olacak. Onlar için beş tunç taban dökeceksin.”"]],27:[["1","“Sunağı akasya ağacından, uzunluğu beş arşın, eni beş arşın olacak şekilde yapacaksın. Sunak kare şeklinde olacak. Yüksekliği üç arşın olacak."],["2","Dört köşesine boynuz yapacaksın. Boynuzları kendisiyle tek parça olacaktır. Onu tunçla kaplayacaksın."],["3","Küllerini uzaklaştırmak için onun kaplarını, küreklerini, leğenlerini, et çatallarını ve ateş kaplarını yapacaksın. Onun bütün takımlarını tunçtan yapacaksın."],["4","Onun için tunç ağdan bir ızgara yapacaksın. Ağın dört köşesine dört tunç halka yapacaksın."],["5","Ağ sunağın yarısına kadar ulaşsın diye onu alttaki sunağın çevresindeki çıkıntının altına koyacaksın."],["6","Sunak için akasya ağacından sırıklar yapacaksın ve onları tunçla kaplayacaksın."],["7","Sırıkları halkalara geçirilecek ve sırıklar sunağı taşırken sunağın iki yanında olacak."],["8","Tahtadan içi boş olarak yapacaksın. Dağda sana gösterildiği gibi yapacaklar.”"],["9","“Konutun avlusunu yapacaksın; güney tarafı için güneye doğru, avlunun bir tarafı için yüz arşın uzunluğunda özenle dokunmuş ince ketenden perdeler olacak."],["10","Yirmi direği, tabanları da yirmi tunçtan olacak. Direklerin çengelleri ve çemberleri gümüşten olacak."],["11","Aynı şekilde kuzey tarafının uzunluğu için de yüz arşın uzunluğunda perdeler, yirmi direk ve tunçtan yirmi tabanları olacak; sütunların çengelleri ve çemberleri gümüşten olacak."],["12","Çünkü avlunun batı tarafında eni elli arşın perde olacak; on direk, on taban olacak."],["13","Avlunun doğuya doğru eni elli arşın olacak."],["14","Kapının bir tarafındaki perdeler on beş arşın olacak; direkleri üç, tabanları da üç olacak."],["15","Diğer tarafta on beş arşınlık perdeler olacak; direkleri üç, tabanları da üç olacak."],["16","Avlunun kapısı için yirmi arşın boyunda mavi, mor, kırmızı, özenle dokunmuş ince ketenden, nakışçı işi bir perde olacak; direkleri dört ve tabanları da dört olacak."],["17","Avlunun çevresindeki tüm direkler gümüşle kaplanacak; çengelleri gümüşten, tabanları tunçtan olacak."],["18","Avlunun uzunluğu yüz arşın, eni elli arşın, yüksekliği beş arşın olacak ve özenle dokunmuş ince ketenden olacak; tabanları tunçtan olacak."],["19","Konutun tüm hizmetinde kullanılan bütün aletleri, bütün kazıkları, avlunun kazıklarının tümü tunçtan olacak.”"],["20","“Şamdan sürekli yansın diye, ışık için sıkma saf zeytinyağı getirmelerini İsrael'in çocuklarına buyuracaksın."],["21","Aron'la oğulları, Buluşma Çadırı'nda, antlaşma önündeki perdenin dışında, onu akşamdan sabaha kadar Yahve'nin önünde tutacaklar; bu, İsrael'in çocukları için kuşaklar boyu daima geçerli bir kural olacaktır.”"]],28:[["1","“İsrael'in çocukları arasından bana kâhinlik makamında hizmet etmeleri için kardeşin Aron'u ve oğulları Nadav'ı, Avihu'yu, Eleazar'ı ve İtimar'ı yanına getir."],["2","Kardeşin Aron'a görkem ve güzellik için kutsal giysiler yapacaksın."],["3","Kendilerini bilgelik ruhuyla doldurduğum tüm bilge yürekli adamlara söyleyeceksin, bana kâhinlik makamında hizmet etmek üzere Aron'un kutsal kılınması için onun giysilerini yapsınlar."],["4","Yapacakları giysiler şunlardır: Göğüslük, efod, kaftan, nakışlı gömlek, sarık ve kuşak. Kardeşin Aron'a ve oğullarına, kâhinlik makamında bana hizmet etmesi için kutsal giysiler yapacaklar."],["5","Altını, maviyi, moru, kırmızıyı ve ince keteni kullanacaklar.”"],["6","“Efodu altın, mavi, mor, kırmızı ve özenle dokunmuş ince ketenden usta işi olarak yapacaklar."],["7","Birbirine bağlanabilmesi için iki ucunda birleştirilmiş iki omuz askısı bulunacak."],["8","Üzerindeki ustalıkla dokunmuş şerit onun işi gibi ve aynı parçadan olacak; altın, mavi, mor, kırmızı ve özenle dokunmuş ince ketenden olacak."],["9","İki oniks taşı alıp üzerlerine İsrael'in çocuklarının adlarını oyacaksın."],["10","Doğum sırasına göre altısının adı bir taşta, altısının adı ise diğer taşta olacak."],["11","İki taşı, İsrael çocuklarının adlarına göre, mühür oyması gibi, taşa oymacı ustalığıyla oyacaksın. Onları altın yuvalar içine koyduracaksın."],["12","İsrael'in çocukları için anma taşları olarak iki taşı efodun omuzluklarına koyacaksın. Aron onların adlarını anılma için Yahve'nin önünde iki omzunda taşıyacak."],["13","Altından yuvalar,"],["14","saf altından iki zincir yapacaksın; onları örgülü kordon gibi yapacaksın. Örgülü zincirleri yuvalara takacaksın.”"],["15","“Hüküm göğüslüğünü usta işi yapacaksın; onu efodun işi gibi yapacaksın; altından, mavi, erguvan, kırmızı ve özenle dokunmuş ince ketenden yapacaksın."],["16","Kare şeklinde ve ikiye katlanmış olacak; bir karış uzunluğu, bir karış da eni olacak."],["17","Oraya dört sıra taş yuvası koyacaksın; ilk sırada yakut, topaz ve beril olacak;"],["18","ve ikinci sırada firuze, safir ve zümrüt;"],["19","üçüncü sırada gök yakut, agat, ametist;"],["20","ve dördüncü sırada sarı yakut, oniks ve yeşim olacak. Onlar altın yuvalarına kakılacak."],["21","Taşlar İsrael çocuklarının adlarına göre on iki adet olacak; mühür oymaları gibi, on iki oymak için her birinin kendi adına göre olacak."],["22","Göğüslük üzerine saf altından örgülü kordon gibi zincirler yapacaksın."],["23","Göğüslük üzerine iki altın halka yapacaksın ve bu iki halkayı göğüslüğün iki ucuna takacaksın."],["24","İki örgülü altın zinciri göğüslüğün uçlarındaki iki halkaya takacaksın."],["25","İki örgü zincirin diğer iki ucunu iki yuvanın üzerine geçirip efodun ön kısmındaki omuzluklara takacaksın."],["26","İki altın halka yapacaksın ve bunları göğüslüğün iki ucuna, efodun iç tarafına doğru olan kenarına takacaksın."],["27","İki altın halka yapacaksın ve bunları efodun iki omuz askısının altına, ön kısmına, bağlantı parçasının yakınına, efodun ustaca dokunmuş şeridinin üstüne takacaksın."],["28","Göğüslüğü halkalarıyla efodun halkaları mavi bir kordonla birbirine bağlayacaklar. Öyle ki, göğüslük efodun ustaca dokunmuş şeridi üzerinde olsun ve göğüslük efodtan ayrılmasın."],["29","Aron, Yahve'nin önünde anılmak üzere kutsal yere girdiğinde, İsrael'in çocuklarının adlarını hüküm göğüslüğünde sürekli olarak yüreği üzerinde taşıyacaktır."],["30","Urim'i ve Tummim'i hüküm göğüslüğüne koyacaksın; Aron Yahve'nin huzuruna girdiğinde bunlar onun yüreği üzerinde olacaklar. Aron, İsrael'in çocuklarının hükmünü Yahve'nin önünde sürekli yüreği üzerinde taşıyacak.”"],["31","“Efodun kaftanını tamamen mavi yapacaksın."],["32","Ortasında baş için bir delik olacak. Yırtılmaması için boşluğunun kenarında, bir zırh deliği gibi dokuma işi bir kenarlık bulunacak."],["33","Etek kısmı boyunca mavi, mor ve kırmızı narlar yapacaksın; tüm etek boyunca aralarında ve çevresinde altın çıngıraklar olacak:"],["34","Kaftanının eteğinde bir altın çıngırak, bir nar, bir altın çıngırak ve bir nar olacak."],["35","Hizmet etme görevi Aron'a ait olacak; kutsal yere Yahve'nin huzuruna girdiğinde ve çıktığında ölmedi diye onun sesi duyulacak.”"],["36","“Saf altından bir levha yapacaksın ve üzerine mühür oyması gibi 'Yahve'ye kutsaldır' yazısını oyacaksın."],["37","Onu mavi bir kordon üzerine koyacaksın, sarığın üzerinde olacak, sarığın ön tarafında olacaktır."],["38","Aron'un alnı üzerinde olacak ve İsrael'in çocuklarının tüm kutsal armağanlarında, bütün kutsal şeylerindeki suçu Aron taşıyacak; ve bunlar Yahve'nin önünde kabul edilsinler diye, bu her zaman onun alnı üzerinde olacaktır."],["39","Gömleği ince ketenden dokuyacaksın. İnce ketenden sarık yapacaksın. Nakışçı işi kuşak yapacaksın.”"],["40","“Aron'un oğulları için gömlekler yapacaksın. Onlar için kuşak yapacaksın. Görkem ve güzellik için onlara başlıklar yapacaksın."],["41","Onları kardeşin Aron'a ve onunla birlikte olan oğullarına giydireceksin; onları meshedeceksin, atayacaksın ve kutsal kılacaksın ki, kâhinlik makamında bana hizmet etsinler."],["42","Onlara çıplak yerlerini örtecek keten donlar yapacaksın. Belden kalçalara kadar uzanacak."],["43","Suç taşıyıp ölmesinler diye, Buluşma Çadırı'na girdiklerinde ya da kutsal yerde hizmet etmek için sunağa yaklaştıklarında Aron'la oğulları üzerinde olacaklar. Bu, hem kendisi hem de kendisinden sonraki soyu için daima bir kural olacaktır.”"]],29:[["1","“Bana kâhinlik makamında hizmet edebilmeleri için onları kutsal kılmak üzere şunları yapacaksın: Kusursuz bir boğa ve iki koç,"],["2","mayasız ekmek, yağla yoğrulmuş mayasız pideler ve yağla meshedilmiş mayasız yufkalar al. Bunları ince buğday unundan yapacaksın."],["3","Onları bir sepete koy, boğa ve iki koçu birlikte getir."],["4","Aron'la oğullarını Buluşma Çadırı'nın kapısına getirip onları suyla yıkayacaksın."],["5","Giysileri al, Aron'a gömleği, efodun kaftanını, efodu ve göğüslüğü giydir, efodun ustaca dokunmuş şeridini ona bağla."],["6","Onun başına sarığı koyacaksın, sarığın üstüne de kutsal tacı koyacaksın."],["7","Sonra mesh yağını alıp başına dökeceksin ve onu meshedeceksin."],["8","Oğullarını getirip üzerlerine gömlek giydireceksin."],["9","Aron'la oğullarına kuşaklar takacaksın, onlara başlıklar bağlayacaksın. Kalıcı bir kuralla kâhinlik onların olacak. Aron'la oğullarını adayacaksın.”"],["10","“Boğayı Buluşma Çadırı'nın önüne getireceksin; Aron ile oğulları ellerini boğanın başına koyacaklar."],["11","Boğayı Yahve'nin önünde, Buluşma Çadırı'nın kapısında keseceksin."],["12","Boğanın kanını alıp parmağınla sunağın boynuzlarına süreceksin; bütün kanı sunağın dibine dökeceksin."],["13","İçini kaplayan yağın tamamını, karaciğerin zarını, iki böbreği ve üzerlerindeki yağı alıp onları sunak üzerinde yakacaksın."],["14","Ancak boğanın etini, derisini ve gübresini ordugâhın dışında ateşle yakacaksın. Bu bir günah sunusudur.”"],["15","“Sen de bir koç alacaksın; Aron'la oğulları ellerini koçun başına koyacaklar."],["16","Koçu keseceksin, kanını alıp sunağın üzerine çepeçevre serpeceksin."],["17","Koçu parçalara ayıracaksın, içini ve bacaklarını yıkayacak, parçalarıyla ve başıyla birlikte koyacaksın."],["18","Koçun tamamını sunak üzerinde yakacaksın; bu Yahve'ye yakmalık bir sunudur; hoş bir kokudur, ateşle Yahve'ye yapılan bir sunudur.”"],["19","“Diğer koçu alacaksın; Aron'la oğulları ellerini koçun başına koyacaklar."],["20","Sonra koçu kesip kanından biraz alacaksın, onu Aron'un sağ kulak memesi üzerine, ve oğullarının sağ kulak memeleri üzerine, ve sağ ellerinin başparmağı üzerine ve sağ ayaklarının başparmağı üzerine koyacaksın; kanı sunağın üzerine serpeceksin."],["21","Sunağın üzerindeki kanı ve mesh yağını alıp Aron'un, onun giysilerinin, oğullarının ve onunla birlikte oğullarının giysilerinin üzerine serpeceksin; o ve onun giysileri, oğulları ve oğullarının giysileri de kendisiyle birlikte kutsal kılınacak."],["22","Ayrıca koçun yağının bir kısmını, kuyruk yağını, içini kaplayan yağı, karaciğerin zarını, iki böbreği, üzerlerindeki yağı ve sağ budu (çünkü o bir adama koçudur),"],["23","Yahve'nin önündeki mayasız ekmek sepetinden bir somun ekmek, bir yağlı pide ve bir de yufka alacaksın."],["24","Bunların hepsini Aron'un ve oğullarının ellerine koyacaksın ve onları sallama sunusu olarak Yahve'nin önünde sallayacaksın."],["25","Onları ellerinden alacaksın ve Yahve'nin önünde hoş bir koku olarak sunak üzerinde yakmalık sunu üzerinde yakacaksın; bu, Yahve'ye ateşle yapılan bir sunudur.”"],["26","“Aron'un adaklık koçunun döşünü alacaksın ve onu Yahve'nin önünde sallama sunusu olarak sallayacaksın. Bu senin payın olacak."],["27","Aron için olan, oğulları için olan adama koçundan, sallanan sallama sunusu döşünü ve kaldırılan kaldırma budunu kutsayacaksın."],["28","Aron için ve oğulları için, İsrael'in çocuklarından daima onların payı olacaktır; çünkü bu bir sallama sunusudur. Bu, İsrael'in çocuklarının esenlik sunularının kurbanlarından sallama sunusu, onların Yahve'ye sallama sunusu olacaktır.”"],["29","“Aron'un kutsal giysileri kendisinden sonra onların meshedilmesi ve kutsanması için oğullarının olacaktır."],["30","Onun yerine kâhin olan oğul, Kutsal Yer'de hizmet etmek üzere Buluşma Çadırı'na girdiğinde bunları yedi gün giyecek.”"],["31","“Adama koçunu alıp etini kutsal bir yerde haşlayacaksın."],["32","Aron'la oğulları koç etini ve sepetteki ekmeği Buluşma Çadırı'nın kapısında yiyecekler."],["33","Onları atayan ve kutsal kılmak için kefaret edilmiş olan şeyleri yiyecekler; ama bir yabancı ondan yemeyecek; çünkü bunlar kutsaldır."],["34","Eğer adama etinden ya da ekmekten sabaha kalırsa, o zaman kalanını ateşte yakacaksın. Yenmeyecektir çünkü kutsaldır.”"],["35","“Sana buyurduğum her şeye göre Aron'la oğullarına böyle yapacaksın. Onları yedi gün adayacaksın."],["36","Her gün günah sunusu olan boğayı kefaret için sunacaksın. Sunak için kefaret ettiğinde onu temizleyeceksin. Onu kutsal kılmak için meshedeceksin."],["37","Yedi gün sunak için kefaret edeceksin ve onu kutsal kılacaksın; sunak çok kutsal olacak. Sunağa dokunan her şey kutsal olacaktır."],["38","“Sunakta sunacağınız budur: Devamlı olarak bir yaşında iki kuzu."],["39","Bir kuzuyu sabahleyin sunacaksın; ve diğer kuzuyu akşam üstü sunacaksın;"],["40","bir kuzuyla birlikte dörtte bir hin sıkma yağla yoğrulmuş onda bir efa ince un ve dökülen sunu olarak dörtte bir hin şarap sunacaksın."],["41","Diğer kuzuyu akşam üstü sunacaksın ve hoş koku, Yahve'ye ateşle yakmalık sunu olarak ona, sabahın ekmek sunusu gibi, dökülen sunu gibi yapacaksın."],["42","Bu, sizinle konuşmak için sizinle buluşacağım Buluşma Çadırı'nın kapısında, Yahve'nin önünde kuşaklarınız boyunca sürekli olarak yakmalık bir sunu olacaktır."],["43","Orada İsrael'in çocuklarıyla buluşacağım; bu yer benim yüceliğim aracılığıyla kutsal kılınacak."],["44","Buluşma Çadırı'nı ve sunağı kutsal kılacağım. Aron'u ve oğullarını da kâhinlik makamında bana hizmet etmeleri için kutsayacağım."],["45","İsrael'in çocukları arasında oturacağım ve onların Tanrısı olacağım."],["46","Aralarında oturmak için kendilerini Mısır diyarından çıkaran Tanrıları Yahve olduğumu bilecekler: Ben onların Tanrısı Yahve'yim.”"]],30:[["1","“Buhur yakmak için bir sunak yapacaksın. Onu akasya ağacından yapacaksın."],["2","Uzunluğu bir arşın, eni bir arşın olacak. Kare şeklinde olacak ve yüksekliği iki arşın olacak. Boynuzları kendisiyle tek parça olacaktır."],["3","Onu, üstünü, yanlarını ve boynuzlarını saf altınla kaplayacaksın; çevresine altın pervaz yapacaksın."],["4","Pervazının altına iki altın halka yapacaksın; iki yanları üzerinde, iki tarafa yapacaksın; bunlar onu taşıyacak sırıklar için yer olacak."],["5","Sırıkları akasya ağacından yapıp altınla kaplayacaksın."],["6","Onu, seninle buluşacağım Antlaşma Sandığı'nın yanındaki perdenin önüne, antlaşma üzerindeki Merhamet Örtüsü'nün önüne koyacaksın."],["7","Aron her sabah onun üzerine hoş baharatlardan buhur yakacak. Kandilleri düzelttiği zaman onu yakacak."],["8","Aron akşam üstü kandilleri yaktığında, onu Yahve'nin önünde kuşaklar boyu sürekli bir buhur olarak yakacak."],["9","Onun üzerinde yabancı buhur, yakmalık sunu ve ekmek sunusu sunmayacaksınız; üzerine dökülen sunudan dökmeyeceksiniz."],["10","Aron yılda bir kez onun boynuzları üzerinde kefaret edecek; yılda bir kez günah kefareti sunusunun kanı ile kuşaklarınız boyunca kefaret edecektir. Yahve için çok kutsaldır.”"],["11","Yahve Moşe'ye söyle dedi:"],["12","“İsrael'in çocuklarının sayımını, aralarında sayılanlara göre yaptığın zaman, saydığında herkes canına karşılık Yahve'ye fidye verecek, ta ki onları saydığın zaman aralarında bela olmasın."],["13","Sayılmış olanlar tarafına geçen herkes, Kutsal Yer'in şekeline göre yarım şekel, (bir şekel yirmi geradır) Yahve'ye sunu olarak yarım şekel verecektir."],["14","Yirmi yaşında ve ondan yukarı olup sayılanlar tarafına geçen herkes, Yahve'ye sunu verecektir."],["15","Canlarınızın kefareti olarak Yahve'ye sunu verdiklerinde, zengin yarım şekelden fazla, yoksul da yarım şekelden az vermeyecektir."],["16","İsrael'in çocuklarından kefaret parasını alıp Buluşma Çadırı'nın hizmetine vereceksin; ta ki bu, canlarınızın kefareti olsun diye, İsrael'in çocuklarına Yahve'nin önünde bir anma olsun.”"],["17","Yahve Moşe'ye şöyle dedi:"],["18","“Yıkanmak için tunçtan bir kazan ve onun ayağını da tunçtan yapacaksın. Onu Buluşma Çadırı ile sunak arasına koyacaksın ve içine su koyacaksın."],["19","Aron'la oğulları ellerini ve ayaklarını onda yıkayacaklar."],["20","Buluşma Çadırı'na girdikleri zaman, ya da hizmet etmek için Yahve'ye ateşle yapılan sunuyu yakmak için sunağa yaklaştıkları zaman, ölmesinler diye suyla yıkanacaklar."],["21","Ölmesinler diye ellerini ve ayaklarını yıkayacaklar. Bu onlara, kendisi ve onun soyundan gelenler için kuşaklar boyu daima bir kural olacaktır.”"],["22","Dahası Yahve Moşe'ye şöyle dedi:"],["23","“Ayrıca güzel baharatlar da al: Beş yüz şekel sıvı mür, yarısı kadar, iki yüz elli şekel hoş kokulu tarçın; iki yüz elli şekel hoş kokulu kamış;"],["24","kutsal yerin şekeline göre beş yüz şekel hıyarşembe ve bir hin zeytinyağı."],["25","Onu kutsal mesh yağı haline getireceksin, attar işine göre hazırlanmış bir hoş koku; kutsal mesh yağı olacak."],["26","Buluşma Çadırı'nı, Antlaşma Sandığı'nı,"],["27","sofrayı ve içindeki bütün eşyaları, şamdan ve takımlarını, buhur sunağını,"],["28","yakmalık sunu sunağını ve tüm takımlarını, kazanı ve ayağını meshetmek için onu kullanacaksın."],["29","Onları kutsal kılacaksın, onlar da çok kutsal olacaklar. Onlara dokunan her şey kutsal olacaktır."],["30","Aron'la oğullarını meshedecek ve onları kutsal kılacaksın ki, onlar bana kâhinlik makamında hizmet etsinler."],["31","İsrael'in çocuklarına şöyle diyeceksin: 'Bu, kuşaklarınız boyunca benim için kutsal mesh yağı olacak."],["32","İnsan bedeni üzerine dökülmeyecek ve derlemesine göre onun benzerini yapmayacaksınız. Bu kutsaldır. Sizin için kutsal olacaktır."],["33","Kim buna benzer bir derleme yaparsa ya da kim ondan bir yabancıya sürerse, halkının arasından atılacaktır.'”"],["34","Yahve Moşe'ye şöyle dedi: “Kendine hoş baharatlar, sakız reçinesi, onika, kasnı: Saf günnük ile hoş baharatlar al. Her birinin ağırlığı eşit olacak."],["35","Ondan, tuzlanmış, saf ve kutsal bir buhur, attar işine göre bir koku yapacaksın."],["36","Bir kısmını çok ince döveceksin ve seninle buluşacağım Buluşma Çadırı'ndaki antlaşmanın önüne koyacaksın. Bu sizin için çok kutsal olacaktır."],["37","Bu buhuru derlemesine göre kendiniz için yapmayacaksınız; o senin için Yahve'ye kutsal olacaktır."],["38","Koklamak için kim buna benzer bir şey yaparsa, halkından atılacaktır.”"]],31:[["1","Yahve Moşe'ye şöyle dedi:"],["2","“İşte, Yahuda oymağından Hur oğlu Uri oğlu Bezalel'i adıyla çağırdım."],["3","Onu Tanrı'nın Ruhu'yla, bilgelikle, anlayışla, bilgiyle ve her türlü ustalıkla doldurdum;"],["4","ta ki, ustaca işler tasarlasın, altında, gümüşde ve tunçda,"],["5","taş kesmede ve kakmada, ağaç oymacılığında ve her çeşit ustalıkta işlesin."],["6","İşte ben de onun yanına Dan oymağından Ahisamak oğlu Oholiav'ı atadım; sana buyurduğum her şeyi yapabilsinler diye, yüreği bilge olanların hepsinin yüreğine bilgelik koydum:"],["7","Buluşma Çadırı'nı, Antlaşma Sandığı'nı, onun üzerindeki Merhamet Örtüsü'nü, Çadır'ın bütün takımlarını,"],["8","masayı ve takımlarını, saf altın şamdanı ve tüm takımlarını, buhur sunağını,"],["9","yakmalık sunu sunağını ve tüm takımlarını, kazanı ve ayağını,"],["10","özenle dokunmuş giysileri, kâhin Aron'un kutsal giysilerini, oğullarının kâhinlik makamında hizmet edecekleri giysilerini;"],["11","mesh yağını ve kutsal yer için hoş baharatlardan oluşan buhuru; sana buyurduğum her şeye göre yapacaklar.”"],["12","Yahve Moşe'ye şöyle dedi:"],["13","“İsrael'in çocuklarına da söyle: 'Şabat günlerimi mutlaka tutacaksınız; çünkü bu, benim sizi kutsayan Yahve olduğumu bilesiniz diye kuşaklar boyu sizinle benim aramda bir belirtidir."],["14","Bunun için Şabat'ı tutacaksınız, çünkü o sizin için kutsaldır. Onu bozan herkes kesinlikle öldürülecektir; çünkü onun içinde her kim bir iş işlerse, o can halkının arasından atılacaktır."],["15","Altı gün iş işlenecek, ama yedinci günde Yahve'ye kutsal dinlenme Şabatı'dır. Şabat Günü'nde iş işleyen herkes kesinlikle öldürülecektir."],["16","Bu nedenle İsrael'in çocukları, daimi bir antlaşma gereği olarak, kuşaklar boyunca Şabat'a uymak için Şabat'ı tutacaklar."],["17","Bu benimle İsrael'in çocukları arasında daima bir belirti olacaktır; çünkü Yahve göğü ve yeri altı günde yarattı ve yedinci günde dinlendi ve rahatladı.'”"],["18","Sina Dağı'nda Moşe'yle konuşmasını bitirince, Tanrı'nın parmağı ile yazılmış olan iki antlaşma levhasını, ona verdi."]],32:[["1","Halk, Moşe'nin dağdan inmekte geciktiğini görünce, Aron'un yanında toplanıp ona şöyle dediler: “Gel, bize önümüzden gidecek ilâhlar yap; çünkü bizi Mısır diyarından çıkaran adama, bu Moşe'ye ne oldu bilmiyoruz.”"],["2","Aron onlara, “Karılarınızın, oğullarınızın, kızlarınızın kulaklarındaki altın yüzükleri çıkarıp bana getirin” dedi."],["3","Bütün halk kulaklarındaki altın küpeleri çıkarıp Aron'a getirdi."],["4","Ona verilenleri aldı, oymacı aletiyle ona şekil verdi ve dökme bir buzağı yaptı. Sonra onlar, “Ey İsrael, seni Mısır diyarından çıkaran ilâhların bunlardır” dediler."],["5","Aron bunu görünce önünde bir sunak yaptı; Aron ilan edip şöyle dedi: “Yarın Yahve'ye bayramdır.”"],["6","Ertesi gün erkenden kalktılar, yakmalık sunuları sındular ve esenlik sunularını getirdiler; insanlar yemek ve içmek için oturdular ve oynamak için kalktılar."],["7","Yahve Moşe'ye şöyle dedi: “Git, aşağı in; çünkü Mısır diyarından çıkardığın halkın bozuldu!"],["8","Onlar kendilerine buyurduğum yoldan çabuk saptılar. Kendileri için dökme bir buzağı yaptılar ve ona tapındılar, ona kurban kestiler ve dediler: Ey İsrael, seni Mısır diyarından çıkaran ilâhların bunlardır dediler.”"],["9","Yahve Moşe'ye şöyle dedi: “Bu halkı gördüm ve işte, onlar sert enseli bir halktır."],["10","Şimdi beni bırak da, onlara karşı öfkem alevlensin ve onları yok edeyim; seni de büyük bir ulus yapacağım.”"],["11","Moşe Tanrısı Yahve'ye yalvarıp şöyle dedi: “Ey Yahve, Mısır diyarından büyük güçle, kudretli elle çıkardığın halkına karşı neden öfken alevleniyor?"],["12","Mısırlılar neden, 'Onları kötülük için, dağlarda öldürmek ve yeryüzünden yok etmek için çıkardı' diye konuşsunlar? Kızgın öfkenden dön ve halkına karşı bu kötülükten vazgeç."],["13","Kendin üzerine ant içtiğin ve onlara, 'Senin soyunu gökteki yıldızlar kadar çoğaltacağım, hakkında söylediğim bütün bu diyarı sizin soyunuza vereceğim, onu sonsuza dek miras alacaklar' dediğin, hizmetkârların Avraham'ı', İshak'ı ve İsrael'i anımsa.”"],["14","Böylece Yahve halkına yapacağını söylediği kötülükten vazgeçti."],["15","Moşe dönüp elinde iki antlaşma levhasıyla dağdan indi; levhaların iki tarafı da yazılıydı. Onların bir tarafına ve öteki tarafına yazılmıştı."],["16","Levhalar Tanrı'nın işiydi ve levhaların üzerine kazınmış olan yazı da Tanrı'nın yazısıydı."],["17","Yeşu, halkın bağırışlarını duyunca Moşe'ye, “Ordugâhta savaş gürültüsü var” dedi."],["18","O şöyle dedi: “Bu, zafer için bağıranların sesi değil. Yenilenlerin de feryat sesi değil bu; ama ben ezgi söyleyenlerin sesini duyuyorum.”"],["19","Ordugâha yaklaştığında buzağıyı ve dans edenleri gördü. O zaman Moşe'nin öfkesi alevlendi ve levhaları elinden fırlattı ve dağın eteğinde onları kırdı."],["20","Yaptıkları buzağıyı alıp ateşte yaktı, toz haline gelinceye kadar ezdi suyun üzerine serpti ve İsrael'in çocuklarına içirdi."],["21","Moşe Aron'a, “Bu halk sana ne yaptı da onların üzerine büyük bir günah getirdin?” dedi."],["22","Aron şöyle dedi: “Efendimin öfkesi alevlenmesin. Halkı sen bilirsin, kötülüğe eğilimlidir."],["23","Çünkü bana, 'Bizim için önümüzden gidecek ilâhlar yap' dediler. “Bizi Mısır diyarından çıkaran adama, bu Moşe'ye ne oldu bilmiyoruz.'"],["24","Ben de onlara, 'Kimde altın varsa çıkarsın' dedim. Onlar da bana verdi; onu ateşe attım ve bu buzağı çıktı.”"],["25","Moşe halkın kontrolden çıktığını görünce (çünkü Aron onları dizginlemediği için düşmanlarının alay konusu olmalarına neden olmuştu),"],["26","Moşe ordugâhın kapısında durdu ve şöyle dedi: “Kim Yahve'nin tarafındaysa, bana gelsin!” Levi'nin bütün oğulları onun yanında toplandılar."],["27","Onlara şöyle dedi: “İsrael'in Tanrısı Yahve şöyle diyor: 'Herkes kılıcını beline kuşansın, ordugâhta kapı kapı dolaşsın ve herkes kendi kardeşini, herkes kendi arkadaşını, ve herkes kendi komşusunu öldürsün.'”"],["28","Levi oğulları Moşe'nin sözüne göre yaptılar. O gün yaklaşık üç bin kişi halktan düştü."],["29","Moşe, “Bugün size bereket versin diye kendinizi Yahve'ye adayın” dedi, “Çünkü herkes oğluna ve kardeşine karşıydı.”"],["30","Ertesi gün Moşe halka şöyle dedi: “Büyük bir günah işlediniz. Şimdi Yahve'nin önüne çıkacağım. Belki günahınız için kefaret ederim.”"],["31","Moşe Yahve'ye dönüp şöyle dedi: “Ah bu halk büyük bir günah işledi ve kendilerine altından ilâhlar yaptılar."],["32","Ama şimdi onların günahlarını bağışlasan—yoksa yazmış olduğun kitabından lütfen beni sil.”"],["33","Yahve Moşe'ye şöyle dedi: “Kim bana karşı günah işlemişse, kitabımdan onu sileceğim."],["34","Şimdi git, halkı sana söylediğim yere götür. İşte, meleğim senin önünden gidecek. Ancak cezalandıracağım gün, onları günahlarından ötürü cezalandıracağım.”"],["35","Çünkü Aron'un yaptığı buzağıya yaptıkları yüzünden Yahve halkı vurdu."]],33:[["1","Yahve Moşe'ye şöyle dedi: “Yola çık, sen ve Mısır diyarından çıkardığın halk Avraham'a, İshak'a ve Yakov'a, 'Senin soyuna vereceğim' diye ant içtiğim diyara buradan çıkın."],["2","Önünden bir melek göndereceğim; Kenanlılar'ı, Amorlular'ı, Hititler'i, Perizziler'i, Hivliler'i ve Yevuslular'ı kovacağım."],["3","Süt ve bal akan ülkeye gidin; ama ben sizin aranıza çıkmayacağım, çünkü siz sert enseli bir halksınız, yoksa yolda sizi tüketirim.”"],["4","Halk bu kötü haberi duyunca yas tuttu; ve kimse takılarını takmadı."],["5","Yahve Moşe'ye şöyle demişti: “İsrael'in çocuklarına de ki, 'Siz sert enseli bir halksınız. Bir an aranıza çıksam, sizi tüketirim. Bu nedenle şimdi takılarını çıkar da sana ne yapacağımı bileyim.’”"],["6","İsrael'in çocukları Horev Dağı'ndan itibaren takılarını çıkardılar."],["7","Moşe çadırı alıp ordugâhın dışına, ordugâhın çok uzağına kurardı ve ona “Buluşma Çadırı” adını verdi. Yahve'yi arayan herkes ordugâhın dışındaki Buluşma Çadırı'na giderdi."],["8","Moşe Çadır'a çıkınca bütün halk ayağa kalkar, herkes kendi çadırının kapısında durup Moşe Çadır'a girene kadar onu izlerdi."],["9","Moşe Çadır'a girince bulut sütuna inip Çadır'ın kapısında dururdu. Yahve Moşe'yle konuşurdu."],["10","Bütün halk bulut sütununun Çadır'ın kapısında durduğunu görürdü. Herkes ayağa kalkıp kendi çadırının kapısında tapınırdı."],["11","Yahve Moşe'yle, bir adamın arkadaşıyla konuştuğu gibi yüz yüze konuşurdu. Tekrar ordugâha dönerdi ama genç bir adam olan hizmetkârı Nun oğlu Yeşu Çadır'dan ayrılmazdı."],["12","Moşe Yahve'ye şöyle dedi: “İşte, sen bana, 'Bu halkı çıkar' diyorsun ama benimle kimi göndereceğini bana söylemedin. Ama sen, 'Seni adınla tanıyorum, sen de benim gözümde lütuf buldun' dedin."],["13","Bu nedenle, eğer senin gözünde lütuf bulduysam, lütfen şimdi bana yolunu göster, ta ki, gözünde lütuf bulayım diye seni bileyim; bu ulusun da senin halkın olduğunu gör.”"],["14","Ve dedi, “Varlığım seninle birlikte gidecek, sana rahat vereceğim.”"],["15","Moşe O'na şöyle dedi: “Eğer varlığın benimle gitmeyecekse, bizi buradan çıkarma."],["16","Benim ve halkının senin gözünde lütuf bulduğumuzu insanlar nasıl bilecek? Senin bizimle gelmenle, böylece benim ve senin halkının yeryüzündeki bütün halklardan ayrılmış olmamızla değil mi?”"],["17","Yahve Moşe'ye şöyle dedi: “Söylediğin bu şeyi de yapacağım; çünkü gözümde lütuf buldun ve seni adınla tanıyorum.”"],["18","Moşe, “Lütfen bana görkemini göster” dedi."],["19","O dedi, “Bütün iyiliğimi önünden geçireceğim ve senin önünde Yahve'nin adını ilan edeceğim. Lütfedeceğim insana lütfedeceğim, merhamet göstereceğim insana merhamet göstereceğim.”"],["20","“Yüzümü göremezsin, çünkü insan beni görüp de yaşayamaz” dedi."],["21","Yahve şunu da dedi: “İşte, yanımda bir yer var ve sen kayanın üzerinde duracaksın."],["22","Böyle olacak, görkemim gelip geçerken, seni bir kaya yarığına koyacağım ve ben oradan geçene kadar seni elimle örteceğim;"],["23","o zaman elimi kaldıracağım, sen de arkamı göreceksin; ama yüzüm görülmeyecek.”"]],34:[["1","Yahve Moşe'ye şöyle dedi: “İlki gibi iki taş levha yont. Kırdığın ilk levhaların üzerinde olan sözleri levhaların üzerine yazacağım."],["2","Sabah hazır ol, sabahleyin Sina Dağı'na çık ve orada, dağın zirvesinde yanıma gel."],["3","Kimse seninle çıkmayacak, dağın hiçbir yerinde kimse görülmeyecek. O dağın önünde sürüler ya da sığırlar otlamasın.”"],["4","İlki gibi iki taş levhayı yonttu; sonra Moşe sabah erkenden kalktı, Yahve'nin kendisine buyurduğu gibi Sina Dağı'na çıktı ve eline iki taş levha aldı."],["5","Yahve bulutun içinde indi, orada onunla durdu ve Yahve'nin adını ilan etti."],["6","Yahve onun önünden geçerken ilan etti: “Yahve! Yahve, merhametli ve lütufkâr, geç öfkelenen, sevgi dolu iyiliği ve gerçeği bol olan,"],["7","binlercesi için sevgi dolu iyiliğini koruyan, haksızlığı, itaatsizliği ve günahı bağışlayan, babaların suçu için çocukları, çocukların üçüncü ve dördüncü kuşaklarını ziyaret ederek suçluyu hiçbir şekilde suçsuz çıkarmayan bir Tanrı'dır.”"],["8","Moşe aceleyle başını yere eğip tapındı."],["9","Ve şöyle dedi: “Eğer şimdi senin gözünde lütuf bulduysam, ey Efendi, ensesi sert bir halk olsa da, lütfen Efendi bizimle birlikte gelsin; suçumuzu ve günahımızı bağışla ve bizi mirasın olarak al.”"],["10","Ve şöyle dedi: “İşte, bir antlaşma yapıyorum. Bütün halkının önünde, ne tüm dünyada, ne de hiçbir ulusta yapılmamış harikalar yapacağım; ve aralarında bulunduğun bütün halk Yahve'nin işini görecek; çünkü seninle yaptığım heybetli bir şeydir."],["11","Bugün sana buyurduğum şeyi tut. İşte, Amorlu, Kenanlı, Hititli, Perizli, Hivli ve Yevuslu'yu senin önünden kovacağım."],["12","Gideceğin ülkede yaşayanlarla antlaşma yapmamaya dikkat et, yoksa aranızda tuzak olur;"],["13","ama onların sunaklarını yıkacaksın, dikili taşlarını parçalayacaksın ve onların Aşera putlarını keseceksin;"],["14","çünkü başka hiçbir ilâha tapmayacaksın; çünkü adı Kıskanç olan Yahve kıskanç bir Tanrı'dır.”"],["15","“Ülkede yaşayanlarla antlaşma yapma, yoksa onların ilâhlarının peşinden fahişelik ederler, ilâhlarına kurban sunarlar, biri seni çağırır, sen de onun kurbanından yersin;"],["16","onların kızlarını oğullarına alırsın ve onların kızları kendi ilâhlarının peşinden fahişelik eder, oğullarını da kendi ilâhlarının ardından fahişelik ettirirler.”"],["17","“Kendiniz için dökme put yapmayacaksın.”"],["18","“Mayasız Ekmek Bayramı'nı tutacaksın. Sana buyurduğum gibi, Aviv ayının belirlenen vaktinde, yedi gün mayasız ekmek yiyeceksin; çünkü Mısır'dan Aviv ayında çıktın.”"],["19","“Rahimi açan her şey; inekten ve koyundan, bütün hayvanlarının ilk doğan erkeklerinin hepsi benimdir."],["20","Eşeğin ilk doğanı için bir kuzunun fidyesini vereceksin. Eğer fidyesini veremeyeceksen, o zaman boynunu kıracaksın. Oğullarının tüm ilk doğanlarının fidyesini vereceksin. Hiç kimse karşımda boş görünmeyecek.”"],["21","“Altı gün çalışacaksın, ama yedinci gün dinleneceksin: Tarla sürme ve hasat zamanında dinleneceksin.”"],["22","“Buğday hasadının ilk ürünleriyle Haftalar Bayramı'nı, yıl sonunda da Hasat Bayramı'nı yapacaksın."],["23","Bütün erkeklerin yılda üç kez İsrael'in Tanrısı Efendi Yahve'nin önünde görünecekler."],["24","Çünkü önündeki ulusları kovacak, sınırlarını genişleteceğim; yılda üç kez Tanrın Yahve'nin önünde görünmek için çıktığında, hiç kimse ülkenizi arzulamayacak.”"],["25","“Kurbanımın kanını mayalı ekmekle sunmayacaksın. Pesah Bayramı kurbanı sabaha bırakılmayacak.”"],["26","“Toprağının ilk seçme ürününü Tanrın Yahve'nin evine getireceksin. “Oğlağı anasının sütünde pişirmeyeceksin.”"],["27","Yahve Moşe'ye şöyle dedi: “Bu sözleri yaz; çünkü bu sözler uyarınca seninle ve İsrael'le bir antlaşma yaptım.”"],["28","Kırk gün kırk gece Yahve'nin yanındaydı; ne ekmek yedi, ne de su içti. Antlaşmanın sözlerini, on buyruğu levhaların üzerine yazdı."],["29","Moşe, elinde iki antlaşma levhasıyla Sina Dağı'ndan indiğinde, dağdan inerken Moşe, O'nunla konuştuğu için yüzünün derisinin parladığını bilmiyordu."],["30","Aron'la bütün İsrael'in çocukları Moşe'yi gördüler, işte, yüzünün derisi parlıyordu; ve onun yanına yaklaşmaya korktular."],["31","Moşe onları çağırdı. Aron'la bütün topluluk önderleri onun yanına döndüler. Moşe onlarla konuştu."],["32","Daha sonra bütün İsrael'in çocukları yaklaştı ve Yahve'nin Sina Dağı'nda kendisine söylemiş olduğu bütün buyrukları onlara verdi."],["33","Moşe onlarla konuşmayı bitirince yüzüne bir peçe koydu."],["34","Ancak Moşe konuşmak için Yahve'nin önüne gittiğinde, dışarı çıkana dek peçeyi kaldırırdı; ve dışarı çıkıp kendisine buyrulanı İsrael'in çocuklarına söylerdi."],["35","İsrael'in çocukları Moşe'nin yüzünü gördüler, Moşe'nin yüzünün derisi parlıyordu; Moşe O'nunla konuşmak için içeri girene kadar peçeyi tekrar yüzüne kordu."]],35:[["1","Moşe İsrael'in çocuklarının bütün topluluğunu toplayıp onlara şöyle dedi: “Yahve'nin yapmanız için buyurduğu şeyler şunlardır."],["2","'Altı gün iş işlenecek, ama yedinci gün sizin için kutsal bir gün, Yahve'ye Şabat, dinlenme günü olacak; onun içinde iş işleyen her kişi öldürülecektir."],["3","Şabat Günü evlerinizde ateş yakmayacaksınız.'”"],["4","Moşe İsrael'in çocuklarının bütün topluluğuna şöyle dedi: “Yahve'nin buyurduğu şey şudur:"],["5","'Aranızda Yahve'ye sunu alın. Yüreği istekli olan herkes, onu Yahve'ye sunu olarak getirsin: Altın, gümüş, tunç,"],["6","mavi, mor, kırmızı, ince keten, keçi kılı,"],["7","kırmızı boyalı koç derileri, deniz ayısı derisi, akasya ağacı,"],["8","ışık için yağ, mesh yağı ve hoş kokulu buhur için baharatlar,"],["9","efod ve göğüslük için oniks ve kakma taşlar.'”"],["10","“'Aranızda bilge yürekli olan her adam gelsin ve Yahve'nin buyurduğu her şeyi:"],["11","Konutu, onun dış kaplamasını, tepesini, kopçalarını, çerçevelerini, kirişlerini, direklerini ve tabanlarını;"],["12","sandığı ve sırıklarını, Merhamet Örtüsü'nü, bölme perdesini;"],["13","masayla sırıklarını, bütün takımlarını ve huzur ekmeğini;"],["14","ışık için şamdanı, onun takımlarını, kandillerini, ışık için yağı;"],["15","buhur sunağını ve sırıklarını, mesh yağını, hoş kokulu buhuru, çadırın kapısındaki kapı perdesini;"],["16","yakmalık sunu sunağını, tunç ızgarasını, sırıklarını, bütün takımlarını, kazanı ve ayağını;"],["17","avlunun perdelerini, direklerini, tabanlarını ve avlu kapısının perdesini;"],["18","konutun kazıklarını, avlunun kazıklarını ve onların iplerini;"],["19","kutsal yerde hizmet etmek için özenle dokunmuş giysiler, kâhin Aron'un kutsal giysileri ve onun oğullarının - kâhinlik makamında hizmet etmek için giysilerini yapsınlar.'”"],["20","İsrael'in çocuklarının bütün topluluğu Moşe'nin önünden ayrıldı."],["21","Yüreği kendisini harekete geçiren ve ruhu istekli olan herkes geldiler ve Buluşma Çadırı'nın işi, tüm hizmetleri ve kutsal giysiler için Yahve'nin sunularını getirdiler."],["22","Erkek olsun kadın olsun, yüreği istekli olan herkes geldi, hepsi Yahve'ye altın sunular sundular, broşlar, küpeler, mühür yüzükleri, bilezikler getirdiler; hepsi altın takıydı."],["23","Yanında mavi, mor, kırmızı, ince keten, keçi kılı, kırmızı boyalı koç derileri ve deniz ayısı derileri bulunan herkes bunları getirdi."],["24","Gümüş ve tunç sunu sunan herkes Yahve'nin sunusunu getirdi; hizmetin herhangi bir işi için yanında akasya ağacı bulunan herkes onu getirdi."],["25","Bilge yürekli kadınların tümü elleriyle eğirdiler ve eğirdikleri mavi, moru, kırmızıyı ve ince keteni getirdiler."],["26","Yürekleri bilgelikle harekete geçen kadınların tümü keçi kılı eğirdiler."],["27","Önderler efod ve göğüslük için oniks taşlarını ve kakma taşlarını;"],["28","ışık için, mesh yağı için ve hoş kokulu buhur için baharatı ve yağı getirdiler."],["29","Yahve'nin Moşe tarafından yapılmasını buyurduğu tüm işler için yürekleri kendilerini istekli kılan her erkek ve kadın, İsrael'in çocukları, Yahve'ye gönüllü sunu getirdiler."],["30","Moşe İsrael'in çocuklarına şöyle dedi: “İşte, Yahve Yahuda oymağından Hur oğlu Uri oğlu Bezalel'i adıyla çağırdı."],["31","Bilgelikte, anlayışta, bilgide ve her türlü ustalıkta;"],["32","altın, gümüş ve tunç işlerken marifetli işler yapmak,"],["33","taş kesmede ve kakmada, ağaç oymacılığında, her türlü ustalık gerektiren işçilikte çalışmak üzere, Tanrı onu kendi ruhuyla doldurdu."],["34","Hem kendisinin hem de Dan oymağından Ahisamak oğlu Oholiav'ın öğretmesini onun yüreğine koydu."],["35","Ve O, oymacılıkta, ustalık işlerinde, mavide, morda, kırmızıda, ince ketende dokuma ve nakış işlerinde, her türlü ustalık işini yapabilmeleri için onları yürek bilgeliğiyle doldurdu, ta ki, herhangi bir işi yapan ve ustaca işler yapanlardan olsunlar."]],36:[["1","“Besalel ile Oholiav, kutsal yerin hizmetiyle ilgili bütün işi Yahve'nin buyurduğu her şeye göre nasıl yapacaklarını bilmek için Yahve'nin bilgelik ve anlayış verdiği her bilge yürekli adamla birlikte çalışacaklardır.”"],["2","Moşe, Besalel'i ve Oholiav'ı, Yahve'nin yüreğine bilgelik koyduğu tüm bilge yürekli adamları, bu işe gelme konusunda yüreği harekete geçen herkesi çağırdı."],["3","İsrael'in çocukları kutsal yerin hizmeti için getirdikleri tüm sunuları Moşe'den aldılar. Her sabah ona gönüllü sunuları getirmeye devam ettiler."],["4","Kutsal yerin bütün işlerini yapan bilgelerin hepsi yapmakta olduğu kendi işinden geldi."],["5","Moşe'ye şöyle dediler: “Halk, Yahve'nin yapın diye buyurduğu iş için gereğinden çok daha fazlasını getirdi.”"],["6","Moşe bir buyruk verdi ve bunu ordugâhın her yerinde ilan ederek şöyle dediler: “Ne erkek ne de kadın kutsal yer için sunu olarak başka bir şey yapmasın.” Böylece halkın getirmesi engellendi."],["7","Çünkü sahip oldukları malzeme bütün işi yapmaya yeter ve fazlasıyla artardı bile."],["8","İşi yapanların arasındaki bilge yürekli kişilerin tümü, konutu mavi, mor ve kırmızı renkte, özenle dokunmuş ince ketenden on perdeyle yaptı. Bunları usta işi Keruvlar'la yaptılar."],["9","Her perdenin uzunluğu yirmi sekiz arşın, her perdenin eni dört arşındı. Bütün perdelerin ölçüsü birdi."],["10","Beş perdeyi birbirine, diğer beş perdeyi de birbirine bağladı."],["11","Takımın kenarından perdelerden birinin kenarına mavi ilmekler yaptı. İkinci takımda perdenin en dıştaki kenarına da aynısını yaptı."],["12","Bir perdede elli ilmek yaptı, ikinci takımdaki perdenin kenarında da elli ilmek yaptı. İlmekler birbirine karşıydılar."],["13","Elli altın kopça yaptı ve perdeleri kopçalarla birbirine bağladı; böylece çadır bir bütün oldu."],["14","Konutun üzerini örtmek için keçi kılından perdeler yaptı. Onlar için on bir perde yaptı."],["15","Her perdenin uzunluğu otuz arşın, eni dört arşındı. On bir perdenin ölçüsü birdi."],["16","Beş perdeyi birbirine, altı perdeyi de birbirine bağladı."],["17","Bir takım perdenin en dıştaki kenarına elli ilmek yaptı, ikinci takımdaki perdenin en dıştaki kenarına da elli ilmek yaptı."],["18","Çadırın tek bir bütün olabilmesi için elli tunç kopça yaptı."],["19","Çadır için kırmızı boyalı koç derilerinden bir örtü, üstüne de deniz ayısı derilerinden bir örtü yaptı."],["20","Konutun çerçevelerini akasya ağacından dikine yaptı."],["21","Bir çerçevenin uzunluğu on arşın, her bir çerçevenin eni bir buçuk arşındı."],["22","Her çerçevenin birbirine bağlı iki kolu vardı. Konutun bütün çerçevelerini bu şekilde yaptı."],["23","Konut için çerçeveleri güneye bakan güney tarafı için yirmi çerçeve yaptı."],["24","Yirmi çerçevenin altına kırk gümüş taban; bir çerçevenin altında iki kol için iki taban, başka bir çerçevenin altında iki kol için iki taban yaptı."],["25","Konutun kuzey tarafındaki ikinci tarafı için yirmi çerçeve,"],["26","bir çerçevenin altında iki taban, diğer bir çerçevenin altında iki taban olmak üzere onların kırk gümüş tabanını yaptı."],["27","Konutun batı tarafındaki uzak kısmı için altı çerçeve yaptı."],["28","Konutun uzak tarafındaki köşeleri için iki çerçeve yaptı."],["29","Altları iki kattı ve aynı şekilde tepeden tek bir halkaya kadar uzanıyorlardı. Bunu iki köşede ikisine de yaptı."],["30","Sekiz çerçeve, her çerçevenin altında iki taban olmak üzere onların on altı gümüş tabanı vardı."],["31","Akasya ağacından konutun bir tarafındaki çerçeveler için beş kiriş,"],["32","konutun diğer tarafındaki çerçeveler için de beş kiriş, batıya bakan arka kısmı için de çadırın çerçeveleri için beş kiriş yaptı."],["33","Ortadaki kirişi çerçevelerin ortasından bir uçtan diğer uca geçecek şekilde yaptı."],["34","Çerçeveleri altınla kapladı, kirişlerin yeri olarak onların halkalarını altın yaptı, kirişleri de altınla kapladı."],["35","Perdeyi mavi, mor, kırmızı ve özenle dokunmuş ince ketenden Keruvlar'la yaptı. Bunu usta işi bir işçilikle yaptı."],["36","Bunun için akasya ağacından dört direk yaptı ve onları altınla kapladı. Çengelleri altındandı. Onlar için dört gümüş taban döktü."],["37","Çadırın kapısına mavi, mor, kırmızı ve özenle dokunmuş ince ketenden nakış işi bir perde;"],["38","ve onun çengelleriyle birlikte beş direği yaptı. Başlıklarını ve çemberlerini altınla kapladı ve beş tabanı da tunçtandı."]],37:[["1","Besalel sandığı akasya ağacından yaptı. Uzunluğu iki buçuk arşın, eni bir buçuk arşın ve yüksekliği bir buçuk arşındı."],["2","Onun içini ve dışını saf altınla kapladı, çevresine de altın pervaz yaptı."],["3","Onun dört ayağına, bir yanına iki halka, öbür yanına iki halka olmak üzere dört altın halka döktü."],["4","Akasya ağacından sırıklar yapıp onları altınla kapladı."],["5","Sandığı taşımak için sırıkları sandığın yanlarındaki halkalara yerleştirdi."],["6","Saf altından bir Merhamet Örtüsü yaptı. Uzunluğu iki buçuk arşın ve eni bir buçuk arşındı."],["7","Altından iki Keruv yaptı. Onları Merhamet Örtüsü'nün iki ucunda dövmeci işi olarak,"],["8","bir uçta bir Keruv, diğer uçta bir Keruv olmak üzere yaptı. Keruvlar'ı iki ucunda Merhamet Örtüsü olacak şekilde tek parça yaptı."],["9","Keruvlar kanatları yukarıya doğru açık, yüzleri birbirine dönük şekilde Merhamet Örtüsü'nü kanatlarıyla örtüyorlardı. Keruvlar'ın yüzleri Merhamet Örtüsü'ne doğruydu."],["10","Masayı akasya ağacından yaptı. Uzunluğu iki arşın, eni bir arşın ve yüksekliği bir buçuk arşındı."],["11","Onu saf altınla kapladı ve çevresine altın pervaz yaptı."],["12","Çevresine bir karış genişliğinde bir kenar, onun çevresine de altın pervaz yaptı."],["13","Onun için dört altın halka döktü ve halkaları dört ayağı üzerinde olan dört köşesine yerleştirdi."],["14","Halkalar kenara, sırıkların masayı taşıyacağı yerlere yakındı."],["15","Masayı taşımak için sırıkları akasya ağacından yaptı ve altınla kapladı."],["16","Masanın üzerindeki kapları, tabakları, kaşıkları, tasları, dökmelik sunu testileri saf altından yaptı."],["17","Şamdanı saf altından yaptı. Onu dövmeci işi olarak yaptı. Tabanı, gövdesi, çanakları, tomurcukları ve çiçekleri ondan tek parçaydı."],["18","Bir yanından üç kol, diğer yanından üç kol olmak üzere şamdanın yanlarından altı kol çıkıyordu;"],["19","bir kolda badem çiçeğine benzer üç çanak, bir tomurcuk, bir çiçek ve diğer kolda ise badem çiçeği şekline benzer üç çanak, bir tomurcuk, bir çiçek vardı; şamdandan çıkan altı kol böyleydi."],["20","Şamdanda badem çiçeğine benzer dört çanak, tomurcukları ve çiçekleri vardı;"],["21","ve ondan çıkan altı kol için, iki kol altında kendisinden bir tomurcuk, iki kol altında kendisinden bir tomurcuk ve iki kol altında kendisinden bir tomurcuk vardı."],["22","Tomurcukları ve kolları ondan tek parçaydı. Hepsi saf altından bir dövmeci işiydi."],["23","Onun yedi kandilini, maşalarını ve tablalarını saf altından yaptı."],["24","Bütün takımlarıyla birlikte onu bir talant saf altından yaptı."],["25","Buhur sunağını akasya ağacından yaptı. Kare şeklindeydi; uzunluğu bir arşın ve eni bir arşındı. Yüksekliği iki arşındı. Boynuzları da onunla tek parçaydı."],["26","Üstünü, yanlarını ve boynuzlarını saf altınla kapladı. Çevresine altın pervaz yaptı."],["27","Onu taşımak için sırık yeri olarak, pervazın altına, iki yanları üzerine ve iki tarafına iki altın halka yaptı."],["28","Sırıkları akasya ağacından yaptı ve altınla kapladı."],["29","Attar işine uygun olarak kutsal mesh yağını ve hoş baharatlardan oluşan saf buhuru yaptı."]],38:[["1","Yakmalık sunu sunağını akasya ağacından yaptı. Kare şeklindeydi. Uzunluğu beş arşın, eni beş arşın ve yüksekliği üç arşındı."],["2","Boynuzlarını dört köşesi üzerine yaptı. Boynuzları onunla tek parçaydı ve onu tunçla kapladı."],["3","Sunağın bütün takımlarını, kovaları, kürekleri, çanakları, çatalları ve ateş kaplarını yaptı. Bütün kaplarını tunçtan yaptı."],["4","Sunak için, etrafındaki çıkıntının altına yarıya kadar uzanan tunç ağ şeklinde bir ızgara yaptı."],["5","Sırıkların yeri olarak tunç ızgaranın dört köşesine dört halka döktü."],["6","Sırıkları akasya ağacından yaptı ve onları tunçla kapladı."],["7","Sırıkları sunağın yanlarındaki halkalara taktı, onu taşımak için kullandı. Onu tahtadan içi boş yaptı."],["8","Buluşma Çadırı'nın kapısında hizmet eden hizmetkâr kadınların aynalarından kazanı ve ayağını tunçtan yaptı."],["9","Avluyu yaptı; güney tarafı için avlunun perdeleri güneye doğru yüz arşın boyunda özenle dokunmuş ince ketendendi;"],["10","yirmi direği ve yirmi tabanı tunçtandı; direklerin çengelleri ve çemberleri gümüştendi."],["11","Kuzey tarafı için yüz arşındı, direkleri yirmi ve tabanları yirmi tunçtandı; direklerin çengelleri ve çemberleri gümüştendi."],["12","Batı tarafında elli arşınlık perdeler, on direk ve on taban vardı; direklerin çengelleri ve çemberleri gümüştendi."],["13","Doğu tarafı için doğuya doğru elli arşındı,"],["14","bir tarafın perdeleri on beş arşındı; direkleri üç, tabanları üç;"],["15","ve diğer tarafta da böyleydi; bu tarafta ve avlu kapısının yanında on beş arşınlık perdeler vardı; direkleri üç, tabanları da üçtü."],["16","Avlunun etrafındaki perdelerin tümü özenle dokunmuş ince ketendendi."],["17","Direklerin tabanları tunçtandı. Direklerin çengelleri ve çemberleri gümüştendi. Başlıkları gümüşle kaplanmıştı. Avlunun tüm direklerinde gümüş şeritler vardı."],["18","Avlu kapısının perdesi mavi, mor, kırmızı ve özenle dokunmuş ketenden nakışçı işiydi. Avlu perdeleri gibi uzunluğu yirmi arşın, eninde yüksekliği ise beş arşındı."],["19","Direkleri dört, tabanları dört tunçtandı; çengelleri gümüşten, başlıklarının kaplamaları ve çemberleri gümüştendi."],["20","Konutun ve avlunun çevresindeki tüm kazıklar tunçtandı."],["21","Antlaşma Çadırı'nda kullanılan malzemelerin miktarları bunlardı; Moşe'nin buyruğu uyarınca Levililer'in hizmeti için kâhin Aron oğlu İtamar'ın eliyle sayıldı."],["22","Yahuda oymağından Hur oğlu Uri oğlu Besalel, Yahve'nin Moşe'ye buyurduğu her şeyi yaptı."],["23","Dan oymağından Ahisamak oğlu, oymacı, usta bir işçi ve mavi, mor, kırmızı ve ince keten kumaşlarda nakışçı olan Oholiav onunla birlikteydi."],["24","Kutsal yerin bütün işlerinde kullanılan altının tamamı, sunu altınıyla birlikte kutsal yerin şekeline göre yirmi dokuz talant ve yedi yüz otuz şekeldi."],["25","Topluluktan sayılanların gümüşü, kutsal yerin şekeline göre yüz talant ve bin yedi yüz yetmiş beş şekeldi;"],["26","yirmi yaşında ve yukarı olan altı yüz üç bin beş yüz elli kişi için, sayılanlar tarafına geçen herkes için, nüfus başına bir beka, yani kutsal yerin şekeline göre yarım şekeldi."],["27","Yüz talant gümüş, kutsal yerin ve perdenin tabanlarının dökümü içindi; yüz talant için yüz taban, taban başına bir talanttı."],["28","Bin yedi yüz yetmiş beş şekelden direkler için çengeller yaptı, direk başlıklarını kapladı ve onlara çemberler yaptı."],["29","Sununun tuncu yetmiş talant ve iki bin dört yüz şekeldi."],["30","Bununla Buluşma Çadırı'nın kapısının tabanlarını, tunç sunağı, onun için olan tunç ızgarayı, sunağın tüm takımlarını,"],["31","avlunun çevresindeki tabanları, avlu kapısının tabanlarını, konutun tüm kazıklarını, avlunun çevresindeki tüm kazıkları yaptı."]],39:[["1","Kutsal yerde hizmet etmek için mavi, mor ve kırmızı renklerden özenle dokunmuş giysiler yaptılar; Yahve'nin Moşe'ye buyurduğu gibi Aron için de kutsal giysiler yaptılar."],["2","Efodu altın, mavi, mor, kırmızı ve özenle dokunmuş ince ketenden yaptı."],["3","Altını dövüp ince levhalar haline getirdiler ve ustalık işçiliği ile mavi, mor, kırmızı ve ince keten arasına işlemek için onu teller halinde kestiler."],["4","Onun için birleştirilmiş omuz askıları yaptılar. İki ucundan birleştirilmişti."],["5","Üzerinde bulunan ve onu tutturmak için kullanılan ustaca dokunmuş şerit de tıpkı onun işi gibi aynı parçadandı, altından, mavi, mor, kırmızı ve özenle dokunmuş ince ketendendi; Yahve'nin Moşe'ye buyurduğu gibiydi."],["6","Altın yuvalar içine kakılmış, İsrael'in çocuklarının adlarına göre mühür oymasıyla oyulmuş, oniks taşlarını işlediler."],["7","Yahve'nin Moşe'ye buyurduğu gibi, İsrael'in çocuklarına anma taşları olsun diye bunları efodun omuz askılarına taktı."],["8","Efodun işi gibi usta işçiliğiyle göğüslüğü altından, mavi, mor, kırmızı ve özenle dokunmuş ince ketenden yaptı."],["9","Kare biçimindeydi. Göğüslüğü iki kat yaptılar. İki katı olarak uzunluğu bir karış, eni bir karıştı."],["10","İçine dört sıra taş dizdiler. İlk sırada bir sıra yakut, topaz ve zümrüt;"],["11","ikinci sırada firuze, safir ve aytaşı;"],["12","üçüncü sırada gökyakut, agat ve ametist;"],["13","dördüncü sırada gökzümrüt, oniks, ve yeşim vardı; yuvalarında altın çerçeveler içine kakılmıştı."],["14","Taşlar İsrael'in çocuklarının adlarına göre, on iki oymak için her birinin kendi adına göre, mühür oymaları gibi adlarına göre, on ikiydi."],["15","Göğüslük üzerine saf altından örmeci işi kordona benzer zincirler yaptılar."],["16","İki altın yuva ve iki altın halka yapıp iki halkayı göğüslüğün iki ucuna taktılar."],["17","İki örme altın zinciri göğüslüğün uçlarındaki iki halkaya taktılar."],["18","İki örme zincirin diğer iki ucunu iki yuva üzerine geçirip efodun ön tarafındaki omuz askılarına taktılar."],["19","İki altın halka yapıp bunları göğüslüğün iki ucuna, efodun iç tarafına doğru olan kenarına taktılar."],["20","İki altın halka daha yapıp efodun iki omuz askısına, efodun ustaca dokunmuş şeridinin üstüne, ön kısmına, birleştiği yerin yakınına taktılar."],["21","Yahve'nin Moşe'ye buyurduğu gibi, efodun ustaca dokunmuş şeridi üzerinde olsun ve göğüslük efodtan ayrılmasın diye, göğüslüğü halkalarıyla efodun halkalarına mavi bir kordonla bağladılar."],["22","Efodun kaftanını tamamen mavi dokuma kumaştan yaptı."],["23","Kaftanının ortasındaki boşluk, bir zırhın boşluğuna benziyordu; boşluğun çevresinde yırtılmaması için bir bağ vardı."],["24","Kaftanın etekleri üzerine mavi, mor, kırmızı ve özenle dokunmuş ketenden narlar yaptılar."],["25","Saf altından çıngıraklar yaptılar ve çıngırakları kaftanın etekleri üzerine çepeçevre narların arasına, narların ara yerlerine;"],["26","Yahve'nin Moşe'ye buyurduğu gibi hizmet etmek için kaftan eteklerinin etrafına bir çıngırak ve bir nar, bir çıngırak ve bir nar şeklinde yaptılar."],["27","Aron'la oğulları için ince ketenden dokunmuş gömlekler,"],["28","ince ketenden sarık, ince ketenden süslü başlıklar, özenle dokunmuş ince ketenden keten donlar,"],["29","özenle dokunmuş ince ketenden mavi, mor, ve kırmızı nakışçı işi kuşaklar, Yahve'nin Moşe'ye buyurmuş olduğu gibi yaptılar."],["30","Kutsal tacın levhasını saf altından yaptılar ve üzerine mühür oymaları gibi “YAHVE'YE KUTSAL” yazısını yazdılar."],["31","Yahve'nin Moşe'ye buyurduğu gibi, yukarıdaki sarığın üzerine bağlamak için ona mavi bir kordon bağladılar."],["32","Böylece Buluşma Çadırı'nın konutuyla ilgili tüm işler tamamlandı. İsrael'in çocukları Yahve'nin Moşe'ye buyurduğu her şeye göre yaptılar; onlar da öyle yaptılar."],["33","Konutu, Çadırı, onun bütün takımlarını, kopçalarını, çerçevelerini, kirişlerini, direklerini, tabanlarını,"],["34","kırmızı boyalı koç derilerinden örtüyü, deniz ayısı derilerinden örtüyü, bölme perdesini,"],["35","sırıklarıyla birlikte Antlaşma Sandığı'nı, Merhamet Örtüsü'nü,"],["36","masayı, bütün takımlarını, huzur ekmeğini,"],["37","saf şamdanı, kandillerini, dizilecek kandillerini, bütün takımlarını, ışık için yağı,"],["38","altın sunağı, mesh yağını, hoş kokulu buhuru, Çadır kapısının perdesini,"],["39","tunç sunağı, onun tunç ızgarasını, sırıklarını, bütün takımlarını, kazanı ve onun ayağını,"],["40","avlu perdelerini, direklerini, tabanlarını, avlu kapısının perdesini, iplerini, kazıklarını ve Buluşma Çadırı için çadırın hizmetinde kullanılan bütün aletleri,"],["41","kutsal yerin hizmeti için özenle dokunmuş giysileri, Kâhin Aron'un kutsal giysilerini ve kâhinlik makamında hizmet edecek oğullarının giysilerini Moşe'ye getirdiler."],["42","İsrael'in çocukları Yahve'nin Moşe'ye buyurduğu her şeye göre bütün işi öyle yaptılar."],["43","Moşe bütün işi gördü ve işte, Yahve'nin buyurduğu gibi yapmışlardı. Öyle yapmışlardı, Moşe de onları kutsadı."]],40:[["1","Yahve Moşe'ye şöyle dedi:"],["2","“Birinci ayın birinci günü Buluşma Çadırı'nın konutunu kuracaksın."],["3","Antlaşma Sandığı'nı içine koyacaksın ve sandığı perdeyle gizleyeceksin."],["4","Masayı içeri getirip üzerindeki şeyleri dizeceksin. Şamdanı getirip kandillerini yakacaksın."],["5","Buhur için altın sunağı Antlaşma Sandığı'nın önüne koyacaksın ve konutun kapısının perdesini takacaksın.”"],["6","“Yakmalık sunu sunağını Buluşma Çadırı'nın konutunun kapısı önüne koyacaksın."],["7","Kazanı Buluşma Çadırı ile sunak arasına koyacaksın ve içine su koyacaksın."],["8","Çevresine avluyu kuracak, avlu kapısının perdesini asacaksın.”"],["9","“Mesh yağını alacaksın, konutu ve içindekilerin hepsini meshedeceksin, onu ve içindeki tüm takımları kutsal kılacaksın ve kutsal olacaktır."],["10","Yakmalık sunu sunağını tüm takımlarıyla birlikte meshedeceksin ve sunağı kutsal kılacaksın; sunak çok kutsal olacak."],["11","Kazanı ve ayağını meshedecek ve onu kutsayacaksın.”"],["12","“Aron'la oğullarını Buluşma Çadırı'nın kapısına getirip onları suyla yıkayacaksın."],["13","Aron'a kutsal giysileri giydireceksin; kâhinlik makamında bana hizmet edebilmesi için onu meshedip kutsal kılacaksın."],["14","Oğullarını getirip üzerlerine gömlekler giydireceksin."],["15","Kâhinlik makamında bana hizmet edebilmeleri için, babalarını meshettiğin gibi onları da meshedeceksin. Meshedilmeleri onlara kuşakları boyunca sonsuz bir kâhinlik için olacaktır.”"],["16","Moşe öyle yaptı. Yahve'nin kendisine buyurduğu her şeye göre, öyle yaptı."],["17","İkinci yılın birinci ayının birinci gününde konut ayağa kaldırıldı."],["18","Moşe konutu kaldırdı, tabanlarını koydu, çerçevelerini yerleştirdi, kirişlerini taktı ve direklerini dikti."],["19","Yahve'nin Moşe'ye buyurduğu gibi örtüyü çadırın üzerine serdi, konutun örtüsünü üst taraftan onun üstüne koydu."],["20","Antlaşmayı alıp sandığın içine koydu, sırıkları sandığa taktı ve Merhamet Örtüsü'nü üst taraftan sandığın üstüne koydu."],["21","Yahve'nin Moşe'ye buyurduğu gibi sandığı konutun içine getirdi, bölme perdesini taktı ve Antlaşma Sandığı'nı gizledi."],["22","Masayı Buluşma Çadırı'na, konutun kuzey tarafına, perdenin dışına koydu."],["23","Yahve'nin Moşe'ye buyurduğu gibi ekmeği onun üzerine Yahve'nin önünde dizdi."],["24","Şamdanı Buluşma Çadırı'nın içine, konutun güneyine, masanın karşısına koydu."],["25","Yahve'nin Moşe'ye buyurduğu gibi, Yahve'nin önünde kandilleri yaktı."],["26","Altın sunağı Buluşma Çadırı'nın içindeki perdenin önüne koydu;"],["27","Yahve'nin Moşe'ye buyurduğu gibi, onun üzerinde hoş kokulu buhur yaktı."],["28","Konutun kapısının perdesini taktı."],["29","Yakmalık sunu sunağını Buluşma Çadırı'nın kapısına koydu ve Yahve'nin Moşe'ye buyurduğu gibi yakmalık sunu ve ekmek sunusunu onun üzerinde sundu."],["30","Kazanı Buluşma Çadırı ile sunak arasına koydu ve içine yıkanmak üzere su koydu."],["31","Moşe, Aron ve oğulları ellerini ve ayaklarını orada yıkadılar."],["32","Buluşma Çadırı'na girip sunağa yaklaştıklarında Yahve'nin Moşe'ye buyurduğu gibi yıkanırlardı."],["33","Avluyu konutun ve sunağın çevresinde yükseltti, avlu kapısının perdesini taktı. Böylece Moşe işi bitirdi."],["34","Sonra bulut Buluşma Çadırı'nı kapladı ve Yahve'nin görkemi konutu doldurdu."],["35","Moşe Buluşma Çadırı'na giremedi; çünkü bulut onun üzerinde duruyordu ve Yahve'nin görkemi çadırı doldurmuştu."],["36","İsrael'in çocukları bütün yolculuklarını, bulut konutun üzerinden kalkınca sürdürürlerdi;"],["37","ama eğer bulut kalkmazsa, kalkacağı güne dek yola çıkmazlardı."],["38","Çünkü bütün yolculukları boyunca, bütün İsrael evinin gözü önünde, Yahve'nin bulutu gündüzleri konutun üzerindeydi, geceleri de bulutta ateş vardı."]]};export{a as default};
